"use strict";(globalThis.webpackChunkcasbin_website||=[]).push([[2673],{3130(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"aws-visual-asset-management-system-casbin","metadata":{"permalink":"/ko/blog/aws-visual-asset-management-system-casbin","editUrl":"https://github.com/apache/casbin-website/edit/master/i18n/ko/docusaurus-plugin-content-blog/2026-11-01-aws-visual-asset-management-system-casbin.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2026-11-01-aws-visual-asset-management-system-casbin.md","title":"AWS\uac00 \uc2dc\uac01\uc801 \uc790\uc0b0 \uad00\ub9ac \uc2dc\uc2a4\ud15c\uc5d0\uc11c Apache Casbin\uc744 \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95","description":"AWS\uc758 \uc624\ud508\uc18c\uc2a4 \uc2dc\uac01\uc801 \uc790\uc0b0 \uad00\ub9ac \uc2dc\uc2a4\ud15c(VAMS)\uc740 API \ub77c\uc6b0\ud2b8 \uac80\uc0ac\ubd80\ud130 \uac1d\uccb4 \uc218\uc900 \uc811\uadfc\uae4c\uc9c0 \uc774\uc5b4\uc9c0\ub294 2\ub2e8\uacc4 ABAC/RBAC \uad8c\ud55c \ubaa8\ub378\uc744 \uc704\ud574 pycasbin\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.","date":"2026-11-01T00:00:00.000Z","tags":[{"inline":true,"label":"casbin","permalink":"/ko/blog/tags/casbin"},{"inline":true,"label":"aws","permalink":"/ko/blog/tags/aws"},{"inline":true,"label":"abac","permalink":"/ko/blog/tags/abac"},{"inline":true,"label":"rbac","permalink":"/ko/blog/tags/rbac"},{"inline":true,"label":"adopters","permalink":"/ko/blog/tags/adopters"}],"readingTime":2.02,"hasTruncateMarker":true,"authors":[{"name":"Yang Luo","title":"Creator of Casbin","url":"https://github.com/hsluoyz","imageURL":"/ko/img/authors/hsluoyz.png","key":"hsluoyz","page":null}],"frontMatter":{"title":"AWS\uac00 \uc2dc\uac01\uc801 \uc790\uc0b0 \uad00\ub9ac \uc2dc\uc2a4\ud15c\uc5d0\uc11c Apache Casbin\uc744 \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95","description":"AWS\uc758 \uc624\ud508\uc18c\uc2a4 \uc2dc\uac01\uc801 \uc790\uc0b0 \uad00\ub9ac \uc2dc\uc2a4\ud15c(VAMS)\uc740 API \ub77c\uc6b0\ud2b8 \uac80\uc0ac\ubd80\ud130 \uac1d\uccb4 \uc218\uc900 \uc811\uadfc\uae4c\uc9c0 \uc774\uc5b4\uc9c0\ub294 2\ub2e8\uacc4 ABAC/RBAC \uad8c\ud55c \ubaa8\ub378\uc744 \uc704\ud574 pycasbin\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.","slug":"aws-visual-asset-management-system-casbin","authors":["hsluoyz"],"tags":["casbin","aws","abac","rbac","adopters"]},"unlisted":false,"nextItem":{"title":"Casbin (Go) v2\uc5d0\uc11c v3\ub85c \uc5c5\uadf8\ub808\uc774\ub4dc: \uc644\uc804\ud55c \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uac00\uc774\ub4dc","permalink":"/ko/blog/upgrading-casbin-go-v2-to-v3"}},"content":"[AWS Visual Asset Management System (VAMS)](https://github.com/awslabs/visual-asset-management-system)\ub294 \ubb3c\ub9ac\uc801 AI\ub97c \uc704\ud55c \uc2dc\uac01\uc801 \uc790\uc0b0 \uad00\ub9ac \ubc0f \ubc30\ud3ec\ub97c \ub2f4\ub2f9\ud558\ub294 AWS\uc758 \uc624\ud508\uc18c\uc2a4 \ud50c\ub7ab\ud3fc\uc785\ub2c8\ub2e4. AWS\uac00 VAMS 2.0\uc744 \ucd9c\uc2dc\ud588\uc744 \ub54c Cognito \uadf8\ub8f9\uc744 Casbin \uae30\ubc18 ABAC/RBAC \uad8c\ud55c \uc2dc\uc2a4\ud15c\uc73c\ub85c \uad50\uccb4\ud588\uc2b5\ub2c8\ub2e4. \ucd5c\uadfc \ubc1c\ud45c\ub41c [2.6 \ub9b4\ub9ac\uc2a4](https://aws.amazon.com/blogs/physical-ai/visual-asset-management-system-2-6-release/)\ub294 \ub3d9\uc77c\ud55c \uc124\uacc4\ub97c \uc720\uc9c0\ud558\uba70 \uadf8 \uc704\uc5d0 \uc911\uc559 \uc9d1\uc911\uc2dd API \uc778\uac00\uc790\ub97c \ucd94\uac00\ud588\uc2b5\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## \ub450 \ub2e8\uacc4, \ud558\ub098\uc758 Enforcer {#two-tiers-one-enforcer}\\n\\nVAMS\ub294 \ubaa8\ub4e0 API \uc694\uccad\uc744 \ub450 \uac1c\uc758 \ub3c5\ub9bd\uc801\uc778 \ub2e8\uacc4\uc5d0 \ub300\ud574 \uac80\uc0ac\ud569\ub2c8\ub2e4. Tier 1\uc740 \uc0ac\uc6a9\uc790\uc758 \uc5ed\ud560\uc774 \uc5d4\ub4dc\ud3ec\uc778\ud2b8\ub97c \ud638\ucd9c\ud560 \uc218 \uc788\ub294\uc9c0 \uacb0\uc815\ud558\uba70, HTTP \uba54\uc11c\ub4dc\ub97c \ub77c\uc6b0\ud2b8 \uacbd\ub85c\uc640 \ube44\uad50\ud569\ub2c8\ub2e4. Tier 2\ub294 \ud574\ub2f9 \uc5ed\ud560\uc774 \ud2b9\uc815 \uac1d\uccb4\uc5d0 \ub300\ud574 \uc791\uc5c5\uc744 \uc218\ud589\ud560 \uc218 \uc788\ub294\uc9c0 \uacb0\uc815\ud558\uba70, \uba54\uc11c\ub4dc\ub97c `databaseId`, `assetName`, `tags`\uc640 \uac19\uc740 \uc5d4\ud2f0\ud2f0 \uc18d\uc131\uacfc \ube44\uad50\ud569\ub2c8\ub2e4. \ub450 \ub2e8\uacc4 \ubaa8\ub450 \uc694\uccad\uc744 \ud5c8\uc6a9\ud574\uc57c \ud569\ub2c8\ub2e4. \ud558\ub098\ub77c\ub3c4 \uac70\ubd80\ub418\uba74 \ud638\ucd9c\uc774 \uac70\ubd80\ub429\ub2c8\ub2e4.\\n\\n\ubc31\uc5d4\ub4dc\ub294 [pycasbin](https://github.com/casbin/pycasbin)\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uac01 \uc0ac\uc6a9\uc790\ub294 \uba54\ubaa8\ub9ac \ub0b4 \ubaa8\ub378\uacfc \ubb38\uc790\uc5f4 \uc5b4\ub311\ud130\ub85c \uad6c\uc131\ub41c `FastEnforcer`\ub97c \uac10\uc2f8\ub294 `CasbinEnforcer`\ub97c \ubc1b\uc2b5\ub2c8\ub2e4. \uc815\ucc45\uc740 DynamoDB\uc5d0 \uc800\uc7a5\ub41c \uc0ac\uc6a9\uc790\uc758 \uc5ed\ud560\uacfc \uc81c\uc57d \uc870\uac74\uc5d0\uc11c \ub7f0\ud0c0\uc784\uc5d0 \uc870\ub9bd\ub418\uba70 \uc0ac\uc6a9\uc790\ubcc4\ub85c 60\ucd08 \ub3d9\uc548 \uce90\uc2dc\ub429\ub2c8\ub2e4. \uc815\ucc45\uc744 \uac00\uc838\uc62c \uc218 \uc5c6\ub294 \uacbd\uc6b0, Enforcer\ub294 \uc2e4\ud328 \uac1c\ubc29(fail open) \ub300\uc2e0 \ubaa8\ub450 \uac70\ubd80(deny-all) \uc815\ucc45\uc73c\ub85c \ud3f4\ubc31\ud569\ub2c8\ub2e4.\\n\\n\ubaa8\ub378\uc758 matcher\ub294 `g(r.sub, p.sub) && eval(p.obj_rule) && r.act == p.act`\uc774\ubbc0\ub85c, \uc5ed\ud560\uc758 \uc81c\uc57d \uc870\uac74\uc740 \ub9ac\uc18c\uc2a4\uc640 \uc791\uc5c5\uc5d0 \ub300\ud55c \uac1d\uccb4 \uc218\uc900 \ud45c\ud604\uc2dd\uc744 \ud3ec\ud568\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. Casbin\uc758 \uc5ed\ud560 \ub9c1\ud06c\ub294 \uc0ac\uc6a9\uc790-\uc5ed\ud560 \ub9e4\ud551\uc744 \ucc98\ub9ac\ud558\uba70, \uc81c\uc57d \uc870\uac74\uc740 ABAC \ubd80\ubd84\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n## 2.6\uc5d0\uc11c\uc758 \ubcc0\uacbd \uc0ac\ud56d {#what-changed-in-26}\\n\\n2.6 \ub9b4\ub9ac\uc2a4\ub294 API \uacc4\uce35\uc744 \uc704\ud55c \ub2e8\uc77c \uc911\uc559 \uc9d1\uc911\uc2dd \uc778\uac00\uc790\ub97c \ucd94\uac00\ud558\uc5ec \uc774\uc804\uc5d0 \uac1c\ubcc4 \ud578\ub4e4\ub7ec\uc5d0 \uc788\ub358 \ub2e4\uc911 \uc694\uc18c \ubc0f \ud074\ub808\uc784 \ub85c\uc9c1\uc744 \ud1b5\ud569\ud588\uc2b5\ub2c8\ub2e4. \ub610\ud55c \uace0\uae09 AWS IAM \uc5ed\ud560 \ub9de\ucda4\ud654\uc640 Cognito OIDC \uc5f0\ub3d9\uc744 \ucd94\uac00\ud588\uc2b5\ub2c8\ub2e4. \uad8c\ud55c \ubd80\uc5ec \ubaa8\ub378 \uc790\uccb4\ub294 \ubcc0\uacbd\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. Casbin\uc740 \uc5ec\uc804\ud788 \ub450 \ub2e8\uacc4\ub97c \ud3c9\uac00\ud558\uba70, \ucee4\uc2a4\ud140 Lambda \uc778\uac00\uc790\ub97c \ud1b5\ud574 IP \uc81c\ud55c\uc744 \ucd94\uac00\ub85c \uc801\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\nVAMS \ubb38\uc11c\ub294 \uc804\uccb4 \ubaa8\ub378, \uac1d\uccb4 \uc720\ud615 \ubc0f \uc81c\uc57d \uc870\uac74 \ud544\ub4dc\ub97c [Permissions Model](https://github.com/awslabs/visual-asset-management-system/blob/main/documentation/docusaurus-site/docs/concepts/permissions-model.md)\uc5d0\uc11c \uc124\uba85\ud569\ub2c8\ub2e4. Enforcer \uad6c\ud604\uc740 [authz \ubaa8\ub4c8](https://github.com/awslabs/visual-asset-management-system/blob/main/backend/backend/handlers/authz/__init__.py)\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## \ub354 \uc54c\uc544\ubcf4\uae30 {#learn-more}\\n\\n- [AWS \ube14\ub85c\uadf8: Visual Asset Management System 2.6 \ub9b4\ub9ac\uc2a4](https://aws.amazon.com/blogs/physical-ai/visual-asset-management-system-2-6-release/)\\n- [GitHub\uc758 VAMS](https://github.com/awslabs/visual-asset-management-system)\\n- [Apache Casbin \ub3c4\uc785 \uc0ac\ub840](https://casbin.apache.org/docs/adopters)\\n\\nAWS\ub294 Apache Casbin\uc744 \uc0ac\uc6a9\ud558\ub294 \uc218\ub9ce\uc740 \uc870\uc9c1 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4. \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c Casbin\uc744 \uc0ac\uc6a9\ud558\ub294 \uacbd\uc6b0, \ub3c4\uc785 \uc0ac\ub840 \ubaa9\ub85d\uc5d0 \ucd94\uac00\ud558\uae30\ub97c \uae30\uaebc\uc774 \ub3c4\uc640\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4."},{"id":"upgrading-casbin-go-v2-to-v3","metadata":{"permalink":"/ko/blog/upgrading-casbin-go-v2-to-v3","editUrl":"https://github.com/apache/casbin-website/edit/master/i18n/ko/docusaurus-plugin-content-blog/2026-02-01-upgrading-casbin-go-v2-to-v3.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2026-02-01-upgrading-casbin-go-v2-to-v3.md","title":"Casbin (Go) v2\uc5d0\uc11c v3\ub85c \uc5c5\uadf8\ub808\uc774\ub4dc: \uc644\uc804\ud55c \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uac00\uc774\ub4dc","description":"\ud504\ub85c\ub355\uc158 \ud658\uacbd\uc5d0\uc11c Casbin v2\ub97c \uc6b4\uc601\ud558\uba70 v3\ub85c\uc758 \uc5c5\uadf8\ub808\uc774\ub4dc \uacbd\ub85c\uac00 \uad81\uae08\ud558\ub2e4\uba74, \uc774 \uac00\uc774\ub4dc\uac00 \uc5ec\ub7ec\ubd84\uc744 \uc704\ud55c \uac83\uc785\ub2c8\ub2e4. \ubcc0\uacbd \uc0ac\ud56d \uc774\ud574\ubd80\ud130 \uc548\uc804\ud55c \ud504\ub85c\ub355\uc158 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uc2e4\ud589\uae4c\uc9c0 \uc804\ud658 \uacfc\uc815\uc5d0 \ud544\uc694\ud55c \ubaa8\ub4e0 \ub0b4\uc6a9\uc744 \ub2e4\ub8f0 \uac83\uc785\ub2c8\ub2e4.","date":"2026-02-01T00:00:00.000Z","tags":[{"inline":true,"label":"casbin","permalink":"/ko/blog/tags/casbin"},{"inline":true,"label":"go","permalink":"/ko/blog/tags/go"},{"inline":true,"label":"migration","permalink":"/ko/blog/tags/migration"},{"inline":true,"label":"upgrade","permalink":"/ko/blog/tags/upgrade"},{"inline":true,"label":"v3","permalink":"/ko/blog/tags/v-3"}],"readingTime":7.04,"hasTruncateMarker":true,"authors":[{"name":"Yang Luo","title":"Creator of Casbin","url":"https://github.com/hsluoyz","imageURL":"/ko/img/authors/hsluoyz.png","key":"hsluoyz","page":null}],"frontMatter":{"title":"Casbin (Go) v2\uc5d0\uc11c v3\ub85c \uc5c5\uadf8\ub808\uc774\ub4dc: \uc644\uc804\ud55c \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uac00\uc774\ub4dc","slug":"upgrading-casbin-go-v2-to-v3","authors":["hsluoyz"],"tags":["casbin","go","migration","upgrade","v3"]},"unlisted":false,"prevItem":{"title":"AWS\uac00 \uc2dc\uac01\uc801 \uc790\uc0b0 \uad00\ub9ac \uc2dc\uc2a4\ud15c\uc5d0\uc11c Apache Casbin\uc744 \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95","permalink":"/ko/blog/aws-visual-asset-management-system-casbin"},"nextItem":{"title":"2025\ub144 Casbin: AI \uc5d0\uc774\uc804\ud2b8 \uc2dc\ub300\uc758 \uc778\uac00","permalink":"/ko/blog/casbin-2025-ai-agent-era"}},"content":"\ud504\ub85c\ub355\uc158 \ud658\uacbd\uc5d0\uc11c Casbin v2\ub97c \uc6b4\uc601\ud558\uba70 v3\ub85c\uc758 \uc5c5\uadf8\ub808\uc774\ub4dc \uacbd\ub85c\uac00 \uad81\uae08\ud558\ub2e4\uba74, \uc774 \uac00\uc774\ub4dc\uac00 \uc5ec\ub7ec\ubd84\uc744 \uc704\ud55c \uac83\uc785\ub2c8\ub2e4. \ubcc0\uacbd \uc0ac\ud56d \uc774\ud574\ubd80\ud130 \uc548\uc804\ud55c \ud504\ub85c\ub355\uc158 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uc2e4\ud589\uae4c\uc9c0 \uc804\ud658 \uacfc\uc815\uc5d0 \ud544\uc694\ud55c \ubaa8\ub4e0 \ub0b4\uc6a9\uc744 \ub2e4\ub8f0 \uac83\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## v3\uc5d0\uc11c \ubb34\uc5c7\uc774 \ubcc0\uacbd\ub418\uc5c8\ub098\uc694? {#what-changed-in-v3}\\n\\n\uc88b\uc740 \uc18c\uc2dd\uc785\ub2c8\ub2e4: **v3\ub294 \uc8fc\ub85c \ubaa8\ub4c8 \uacbd\ub85c \ubcc0\uacbd\uc774\uba70 \uc644\uc804\ud55c \ud558\uc704 \ud638\ud658\uc131\uc744 \uc720\uc9c0\ud569\ub2c8\ub2e4**. \ud575\uc2ec \uc778\uac00 \ub85c\uc9c1, API \ubc0f \uae30\ub2a5\uc740 \ubcc0\uacbd\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \uc774\ub294 Go\uc758 \uc2dc\ub9e8\ud2f1 \ubc84\uc804 \uad00\ub9ac \uaddc\uc57d\uc744 \ub530\ub974\uba74\uc11c \ud63c\ub780\uc744 \ucd5c\uc18c\ud654\ud558\uae30 \uc704\ud55c \uc758\ub3c4\uc801\uc778 \uacb0\uc815\uc774\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n### \uc8fc\uc694 \ubcc0\uacbd \uc0ac\ud56d: \ubaa8\ub4c8 \uacbd\ub85c {#the-main-change-module-path}\\n\\nv3\uc5d0\uc11c\uc758 \uc720\uc77c\ud55c \ud30c\uad34\uc801 \ubcc0\uacbd \uc0ac\ud56d\uc740 Go \ubaa8\ub4c8 \uacbd\ub85c\uc785\ub2c8\ub2e4:\\n\\n```go\\n// v2\\nimport \\"github.com/casbin/casbin/v2\\"\\n\\n// v3\\nimport \\"github.com/casbin/casbin/v3\\"\\n```\\n\\n\uc774\uac83\uc774 \uc804\ubd80\uc785\ub2c8\ub2e4. \uae30\uc874 \uc815\ucc45, \ubaa8\ub378 \ubc0f \ucf54\ub4dc \ub85c\uc9c1\uc740 \ubcc0\uacbd\ud560 \ud544\uc694\uac00 \uc5c6\uc2b5\ub2c8\ub2e4. \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc740 \uae30\uacc4\uc801\uc785\ub2c8\ub2e4: import \ubb38\uacfc go.mod \ud30c\uc77c\uc744 \uc5c5\ub370\uc774\ud2b8\ud558\uc138\uc694.\\n\\n### \uc65c v3\ub97c \ub9b4\ub9ac\uc2a4\ud588\ub098\uc694? {#why-release-v3}\\n\\n\ub2e8\uc21c\ud55c import \uacbd\ub85c \ubcc0\uacbd\ub9cc\uc73c\ub85c \uc0c8\ub85c\uc6b4 \uc8fc\uc694 \ubc84\uc804\uc744 \ub9b4\ub9ac\uc2a4\ud55c \uc774\uc720\uc5d0 \ub300\ud574 \uc758\ubb38\uc774 \ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc815\ub2f5\uc740 \uc2dc\ub9e8\ud2f1 \ubc84\uc804 \uad00\ub9ac\uc785\ub2c8\ub2e4. Go\uc758 \ubaa8\ub4c8 \uc2dc\uc2a4\ud15c\uc740 import \uacbd\ub85c(`/v2`, `/v3` \ub4f1)\uc5d0 \uc8fc\uc694 \ubc84\uc804 \ubc88\ud638\ub97c \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uc774\ub97c \ud1b5\ud574 \ub3d9\uc77c\ud55c \uc758\uc874\uc131 \ud2b8\ub9ac\uc5d0 \uc5ec\ub7ec \uc8fc\uc694 \ubc84\uc804\uc774 \uacf5\uc874\ud560 \uc218 \uc788\uc73c\uba70, \uc774\ub294 \ub9ce\uc740 \uc758\uc874\uc131\uc744 \uac00\uc9c4 \ub300\uaddc\ubaa8 \uc560\ud50c\ub9ac\ucf00\uc774\uc158\uc5d0 \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4.\\n\\nv3\ub97c \ub9b4\ub9ac\uc2a4\ud568\uc73c\ub85c\uc368 \uc800\ud76c\ub294 \ub2e4\uc74c\uc744 \uc218\ud589\ud588\uc2b5\ub2c8\ub2e4:\\n- Go\uc758 \uc2dc\ub9e8\ud2f1 import \ubc84\uc804 \uad00\ub9ac\uc640 \uc815\ub82c\\n- \ubcf5\uc7a1\ud55c \uc758\uc874\uc131 \uadf8\ub798\ud504\uc5d0\uc11c\uc758 \uc810\uc9c4\uc801 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \ud65c\uc131\ud654\\n- \uae30\uc874 v2 \uc0ac\uc6a9\uc790\ub97c \uae68\ub728\ub9ac\uc9c0 \uc54a\uc73c\uba74\uc11c \ud5a5\ud6c4 \ud5a5\uc0c1\uc744 \uc704\ud55c \uae30\ubc18 \ub9c8\ub828\\n\\n## \ubb34\uc5c7\uc774 \ub3d9\uc77c\ud558\uac8c \uc720\uc9c0\ub418\uc5c8\ub098\uc694? {#what-stayed-the-same}\\n\\n\uadf8 \uc678 \ubaa8\ub4e0 \uac83. \uc9c4\uc2ec\uc785\ub2c8\ub2e4.\\n\\n- **\ubaa8\ub4e0 API\ub294 \ub3d9\uc77c\ud558\uac8c \uc720\uc9c0\ub429\ub2c8\ub2e4** - `Enforce()`, `AddPolicy()`, `GetAllRoles()` \ubc0f \uae30\ud0c0 \ubaa8\ub4e0 \uba54\uc11c\ub4dc\ub294 \uc774\uc804\uacfc \uc815\ud655\ud788 \ub3d9\uc77c\ud558\uac8c \uc791\ub3d9\ud569\ub2c8\ub2e4\\n- **\ubaa8\ub378 \ubc0f \uc815\ucc45 \uad6c\ubb38 \ubcc0\uacbd \uc5c6\uc74c** - \uae30\uc874 `.conf` \ubaa8\ub378 \ud30c\uc77c\uacfc `.csv` \uc815\ucc45 \ud30c\uc77c\uc740 \uc218\uc815 \uc5c6\uc774 \uc791\ub3d9\ud569\ub2c8\ub2e4\\n- **Adapter \uc778\ud130\ud398\uc774\uc2a4 \ubcc0\uacbd \uc5c6\uc74c** - `persist.Adapter` \uba54\uc11c\ub4dc\ub294 \ub3d9\uc77c\ud569\ub2c8\ub2e4; \uc5b4\ub311\ud130\uc5d0\ub294 v3 \ubaa8\ub4c8 \uacbd\ub85c\ub97c \uae30\uc900\uc73c\ub85c \ube4c\ub4dc\ub41c \ub9b4\ub9ac\uc2a4\ub9cc \ud544\uc694\ud569\ub2c8\ub2e4\\n- **\uc131\ub2a5 \ud2b9\uc131** - \uc131\ub2a5 \uc800\ud558\ub098 \ud5a5\uc0c1 \uc5c6\uc74c; \ub3d9\uc77c\ud55c \uc5d4\uc9c4\uc785\ub2c8\ub2e4\\n- **\ubbf8\ub4e4\uc6e8\uc5b4 \ud1b5\ud569** - \ubbf8\ub4e4\uc6e8\uc5b4\ub294 enforcer\uc640 \ub3d9\uc77c\ud55c \uc8fc\uc694 \ubc84\uc804\uc744 import\ud558\uba74 \ub3d9\uc77c\ud55c \ubc29\uc2dd\uc73c\ub85c \uc791\ub3d9\ud569\ub2c8\ub2e4\\n\\n## v3\uc758 \uc0c8\ub85c\uc6b4 \uae30\ub2a5 {#new-features-in-v3}\\n\\n2025\ub144 12\uc6d4 v3.0.0 \ub9b4\ub9ac\uc2a4 \uc774\ud6c4 \uba87 \uac00\uc9c0 \uc0c8\ub85c\uc6b4 \uae30\ub2a5\uc774 \ucd94\uac00\ub418\uc5c8\uc2b5\ub2c8\ub2e4:\\n\\n### v3.7.0+: \uac15\ud654\ub41c Logger \ud1b5\ud569 {#v370-enhanced-logger-integration}\\n\uc774\uc81c Casbin\uc758 \ud575\uc2ec \uc778\uac00 \ubc0f \uc815\ucc45 \uad00\ub9ac \uc791\uc5c5\uc5d0 \uc0ac\uc6a9\uc790 \uc9c0\uc815 \ub85c\uac70\ub97c \ud1b5\ud569\ud558\uc5ec \uac00\uc2dc\uc131\uc744 \ub192\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4:\\n\\n```go\\nenforcer.SetLogger(yourCustomLogger)\\n```\\n\\n### v3.8.0+: GetAllUsers() API\\n\uc0ac\uc6a9\uc790\uc640 \uc5ed\ud560\uc744 \uad6c\ubd84\ud558\uae30 \uc704\ud55c \uc0c8\ub85c\uc6b4 API:\\n\\n```go\\nusers, err := enforcer.GetAllUsers()\\n```\\n\\n\uc5ed\ud560 \uc815\uc758\uc640 \ubcc4\ub3c4\ub85c \uc2e4\uc81c \uc0ac\uc6a9\uc790 \ubaa9\ub85d\uc744 \ud45c\uc2dc\ud574\uc57c \ud558\ub294 RBAC \uc2dc\uc2a4\ud15c\uc5d0\uc11c \ud2b9\ud788 \uc720\uc6a9\ud569\ub2c8\ub2e4.\\n\\n### v3.9.0+: \ub0b4\uc7a5 \uc21c\ud658 \uac80\ucd9c {#v390-built-in-cycle-detection}\\nenforcer\ub294 \uc774\uc81c \uc5ed\ud560 \uacc4\uce35 \uad6c\uc870\uc758 \uc21c\ud658\uc744 \uc790\ub3d9\uc73c\ub85c \uac10\uc9c0\ud558\uc5ec \ubb34\ud55c \ub8e8\ud504\ub97c \ubc29\uc9c0\ud569\ub2c8\ub2e4:\\n\\n```go\\n// Automatically detects and prevents circular role assignments\\nenforcer.AddGroupingPolicy(\\"alice\\", \\"admin\\")\\nenforcer.AddGroupingPolicy(\\"admin\\", \\"alice\\") // Will be detected as a cycle\\n```\\n\\n### v3.10.0+: AI \uae30\ubc18 \uc778\uac00 \ud1b5\ucc30\ub825\uc744 \uc704\ud55c Explain() API {#v3100-explain-api-for-ai-powered-authorization-insights}\\n\ucd5c\uc2e0 \uae30\ub2a5\uc740 LLM API\ub97c \ud65c\uc6a9\ud558\uc5ec \uc778\uac00 \uacb0\uc815\uc744 \uc790\uc5f0\uc5b4\ub85c \uc124\uba85\ud569\ub2c8\ub2e4:\\n\\n```go\\nenforcer.SetAIConfig(casbin.AIConfig{\\n    Endpoint: \\"https://api.openai.com/v1/chat/completions\\",\\n    APIKey:   os.Getenv(\\"OPENAI_API_KEY\\"),\\n    Model:    \\"gpt-4\\",\\n})\\n\\nexplanation, err := enforcer.Explain(\\"alice\\", \\"data1\\", \\"read\\")\\n// e.g. \\"Alice can read data1 because she has the \'reader\' role...\\"\\n```\\n\\n\uc774\ub294 \ubcf5\uc7a1\ud55c \uc815\ucc45\uc744 \ub514\ubc84\uae45\ud558\uace0 \ube44\uae30\uc220\uc801 \uc774\ud574\uad00\uacc4\uc790\uac00 \uc778\uac00 \uacb0\uc815\uc744 \uc774\ud574\ud558\ub294 \ub370 \ud2b9\ud788 \uac00\uce58\uac00 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## **Migration Strategy** {#migration-strategy}\\n\\n### **For New Projects** {#for-new-projects}\\n\\n\uac04\ub2e8\ud569\ub2c8\ub2e4. \ucc98\uc74c\ubd80\ud130 v3\uc744 \uc0ac\uc6a9\ud558\uc138\uc694.\\n\\n```bash\\ngo get github.com/casbin/casbin/v3\\n```\\n\\n```go\\nimport \\"github.com/casbin/casbin/v3\\"\\n```\\n\\n### **For Existing v2 Projects** {#for-existing-v2-projects}\\n\\n\ub9c8\uc774\uadf8\ub808\uc774\uc158\uc5d0\ub294 \uc138 \ub2e8\uacc4\uac00 \ud3ec\ud568\ub429\ub2c8\ub2e4:\\n\\n#### **Step 1: Update Your go.mod** {#step-1-update-your-gomod}\\n\\n```bash\\ngo get github.com/casbin/casbin/v3\\ngo mod tidy\\n```\\n\\n#### **Step 2: Update Import Statements** {#step-2-update-import-statements}\\n\\n\ucf54\ub4dc\ubca0\uc774\uc2a4 \uc804\uccb4\uc5d0\uc11c \ubaa8\ub4e0 Casbin import\ub97c \ucc3e\uc544 \uad50\uccb4\ud558\uc138\uc694:\\n\\n```bash\\n# Using sed on Unix/Linux/Mac\\nfind . -type f -name \'*.go\' -exec sed -i \'s|github.com/casbin/casbin/v2|github.com/casbin/casbin/v3|g\' {} +\\n\\n# Or manually in your editor\\n# Find: github.com/casbin/casbin/v2\\n# Replace: github.com/casbin/casbin/v3\\n```\\n\\n#### **Step 3: Update Adapter Imports (If Applicable)** {#step-3-update-adapter-imports-if-applicable}\\n\\nAdapter\ub294 \ud2b9\uc815 \uc8fc\uc694 \ubc84\uc804\uc758 `persist.Adapter`\ub97c \uad6c\ud604\ud569\ub2c8\ub2e4. \uc65c\ub0d0\ud558\uba74 `casbin/v2`\uc640 `casbin/v3`\uc758 `model.Model`\uc740 \uc11c\ub85c \ub2e4\ub978 Go \ud0c0\uc785\uc774\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \ub530\ub77c\uc11c v3 enforcer\ub294 `github.com/casbin/casbin/v3`\ub97c import\ud558\ub294 adapter \ub9b4\ub9ac\uc2a4\uac00 \ud544\uc694\ud569\ub2c8\ub2e4. adapter\uc758 `go.mod`\ub97c \ud655\uc778\ud558\uc138\uc694:\\n\\n```go\\n// Example: the PostgreSQL adapter already depends on casbin/v3\\nimport pgadapter \\"github.com/apache/casbin-pg-adapter\\"\\n\\n// The file adapter is built in and ships with each major version\\n```\\n\\nadapter\uac00 \uc544\uc9c1 \uc5c5\ub370\uc774\ud2b8\ub418\uc9c0 \uc54a\uc558\ub2e4\uba74, \uc5c5\ub370\uc774\ud2b8\ub420 \ub54c\uae4c\uc9c0 \ud574\ub2f9 \uc11c\ube44\uc2a4\ub294 v2\uc5d0 \uc720\uc9c0\ud558\uac70\ub098 adapter \uc800\uc7a5\uc18c\uc5d0 issue\ub97c \ub4f1\ub85d\ud558\uc138\uc694.\\n\\n### **Rollback Plan** {#rollback-plan}\\n\\n\ub864\ubc31\uc774 \ud544\uc694\ud55c \uacbd\uc6b0:\\n\\n1. **Code level**: import \ubcc0\uacbd \uc0ac\ud56d\uc744 \ub418\ub3cc\ub9bd\ub2c8\ub2e4(\ubc84\uc804 \ucee8\ud2b8\ub864 \uc0ac\uc6a9).\\n2. **Dependency level**: `go get github.com/casbin/casbin/v2@latest`\\n3. **Deploy**: \ud45c\uc900 \ubc30\ud3ec \ud504\ub85c\uc138\uc2a4\ub97c \uc0ac\uc6a9\ud558\uc5ec \ub418\ub3cc\ub9bd\ub2c8\ub2e4.\\n\\n\uc774 \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc758 \uc7a5\uc810\uc740 \ub864\ubc31\uc774 \ub9e4\uc6b0 \uac04\ub2e8\ud558\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4. import \ubcc0\uacbd \uc0ac\ud56d\uc744 \ub418\ub3cc\ub9ac\uace0 \ub2e4\uc2dc \ubc30\ud3ec\ud558\uae30\ub9cc \ud558\uba74 \ub429\ub2c8\ub2e4.\\n\\n## **Do I Need to Migrate My Policy Database?** {#do-i-need-to-migrate-my-policy-database}\\n\\n**\uc544\ub2c8\uc694.** \uae30\uc874 \uc815\ucc45 \ub370\uc774\ud130\ub294 \ubcc0\uacbd\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc815\ucc45\uc740 \uac04\ub2e8\ud55c \ubb38\uc790\uc5f4(subject, object, action \ub4f1)\ub85c \uc800\uc7a5\ub418\uba70 Casbin \ubc84\uc804\uc5d0 \uc758\uc874\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n## **Testing Your Migration** {#testing-your-migration}\\n\\n### **Automated Testing** {#automated-testing}\\n\\n\uae30\uc874 \ud14c\uc2a4\ud2b8\ub294 \uc218\uc815 \uc5c6\uc774 \ud1b5\uacfc\ud574\uc57c \ud569\ub2c8\ub2e4:\\n\\n```go\\nfunc TestPolicyEnforcement(t *testing.T) {\\n    // This test works identically in v2 and v3\\n    e, _ := casbin.NewEnforcer(\\"model.conf\\", \\"policy.csv\\")\\n    \\n    ok, _ := e.Enforce(\\"alice\\", \\"data1\\", \\"read\\")\\n    if !ok {\\n        t.Error(\\"Expected alice to have read access to data1\\")\\n    }\\n}\\n```\\n\\n### **Integration Testing** {#integration-testing}\\n\\n`*casbin.Enforcer`\ub97c \uc0ac\uc6a9\ud558\ub294 middleware\ub294 adapter\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \ud558\ub098\uc758 \uc8fc\uc694 \ubc84\uc804\uc5d0 \uc885\uc18d\ub429\ub2c8\ub2e4. middleware\uac00 \uc5ec\uc804\ud788 `casbin/v2`\ub97c import\ud55c\ub2e4\uba74, enforcer\ub97c \uc9c1\uc811 \ud638\ucd9c\ud558\ub294 \uac83\uc740 \uba87 \uc904\uc758 \ucf54\ub4dc\uba74 \ucda9\ubd84\ud569\ub2c8\ub2e4:\\n\\n```go\\n// Example with Gin\\nimport (\\n    \\"net/http\\"\\n\\n    \\"github.com/casbin/casbin/v3\\"\\n    \\"github.com/gin-gonic/gin\\"\\n)\\n\\nfunc Authorizer(e *casbin.Enforcer) gin.HandlerFunc {\\n    return func(c *gin.Context) {\\n        ok, err := e.Enforce(c.GetString(\\"user\\"), c.Request.URL.Path, c.Request.Method)\\n        if err != nil || !ok {\\n            c.AbortWithStatus(http.StatusForbidden)\\n            return\\n        }\\n        c.Next()\\n    }\\n}\\n```\\n\\n### **Load Testing** {#load-testing}\\n\\nv3 \ube4c\ub4dc\uc5d0 \ub300\ud574 \ud45c\uc900 \ubd80\ud558 \ud14c\uc2a4\ud2b8\ub97c \uc2e4\ud589\ud558\uc138\uc694. \uc131\ub2a5 \ud2b9\uc131\uc740 v2\uc640 \ub3d9\uc77c\ud574\uc57c \ud569\ub2c8\ub2e4.\\n\\n### **Policy Verification** {#policy-verification}\\n\\n\ubc84\uc804 \uac04 \uc815\ucc45 \ud3c9\uac00\ub97c \ube44\uad50\ud558\uc138\uc694:\\n\\n```bash\\n# Export policies from v2\\n# Load into v3\\n# Run test cases against both\\n# Compare results\\n```\\n\\n\ucc28\uc774\uac00 \ubc1c\uacac\ub418\uba74 \ubc84\uadf8\uc77c \uac00\ub2a5\uc131\uc774 \ub192\uc2b5\ub2c8\ub2e4. \uc2e0\uace0\ud574 \uc8fc\uc138\uc694!\\n\\n## **Common Pitfalls** {#common-pitfalls}\\n\\n### **Pitfall 1: Mixed v2/v3 Dependencies** {#pitfall-1-mixed-v2v3-dependencies}\\n\\n**Problem**: \uc77c\ubd80 \uc758\uc874\uc131\uc740 Casbin v2\ub97c \uc0ac\uc6a9\ud558\uace0 \ub2e4\ub978 \uc758\uc874\uc131\uc740 v3\ub97c \uc0ac\uc6a9\ud558\uc5ec \ucda9\ub3cc\uc774 \ubc1c\uc0dd\ud569\ub2c8\ub2e4.\\n\\n**Solution**: \ube4c\ub4dc \uc790\uccb4\ub294 \ubb38\uc81c\uc5c6\uc2b5\ub2c8\ub2e4. Go \ubaa8\ub4c8 \uc2dc\uc2a4\ud15c\uc740 v2\uc640 v3\ub97c \ubcc4\ub3c4\uc758 \ud328\ud0a4\uc9c0\ub85c \ucc98\ub9ac\ud558\ubbc0\ub85c \ub458 \ub2e4 \ub3d9\uc77c\ud55c \uc758\uc874\uc131 \ud2b8\ub9ac\uc5d0 \uc874\uc7ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc v3 enforcer\ub97c v2\ub97c \uae30\ub300\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0 \uc804\ub2ec\ud558\ub294 \uac83\uc740 \ubd88\uac00\ub2a5\ud569\ub2c8\ub2e4. enforcer, adapter \ubc0f middleware\ub97c \ub3d9\uc77c\ud55c \uc8fc\uc694 \ubc84\uc804\uc73c\ub85c \uc720\uc9c0\ud558\uc138\uc694.\\n\\n### **Pitfall 2: Adapter Version Mismatch** {#pitfall-2-adapter-version-mismatch}\\n\\n**Problem**: Casbin v3\uc640 \ud568\uaed8 v2 adapter\ub97c \uc0ac\uc6a9\ud558\uac70\ub098 \uadf8 \ubc18\ub300\uc758 \uacbd\uc6b0\uc785\ub2c8\ub2e4.\\n\\n**Solution**: \uc774\ub294 \ub7f0\ud0c0\uc784 \uc608\uc678\uac00 \uc544\ub2cc \ucef4\ud30c\uc77c \uc624\ub958\ub85c \ub098\ud0c0\ub0a9\ub2c8\ub2e4. adapter\uc758 `go.mod`\uac00 \uc694\uad6c\ud558\ub294 Casbin \uc8fc\uc694 \ubc84\uc804\uc744 \ud655\uc778\ud558\uace0 enforcer\uc640 \uc77c\uce58\ud558\ub294 \ub9b4\ub9ac\uc2a4\ub97c \uc0ac\uc6a9\ud558\uc138\uc694.\\n\\n### **Pitfall 3: Forgetting Internal Packages** {#pitfall-3-forgetting-internal-packages}\\n\\n**Problem**: \uba54\uc778 \uc560\ud50c\ub9ac\ucf00\uc774\uc158\uc758 import\ub294 \uc5c5\ub370\uc774\ud2b8\ud588\uc9c0\ub9cc \ub0b4\ubd80 \ud328\ud0a4\uc9c0\ub098 \ub3c4\uad6c\ub97c \uc78a\uc5b4\ubc84\ub9b0 \uacbd\uc6b0\uc785\ub2c8\ub2e4.\\n\\n**Solution**: `go mod graph`\uc640 `go mod why`\ub97c \uc0ac\uc6a9\ud558\uc5ec \ubaa8\ub4e0 Casbin \uc758\uc874\uc131\uc744 \ucc3e\uc73c\uc138\uc694:\\n\\n```bash\\ngo mod graph | grep casbin\\n```\\n\\n### **Pitfall 4: Custom Adapter Compilation Issues** {#pitfall-4-custom-adapter-compilation-issues}\\n\\n**\ubb38\uc81c**: \uc5c5\uadf8\ub808\uc774\ub4dc \ud6c4 \ucee4\uc2a4\ud140 \uc5b4\ub311\ud130\uac00 \ucef4\ud30c\uc77c\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n**\ud574\uacb0\ucc45**: \uc5b4\ub311\ud130 \uc778\ud130\ud398\uc774\uc2a4\ub294 \ubcc0\uacbd\ub418\uc9c0 \uc54a\uc558\uc73c\ubbc0\ub85c \uc774\ub294 import \ubb38\uc81c\uc77c \uac00\ub2a5\uc131\uc774 \ub192\uc2b5\ub2c8\ub2e4. \uc5b4\ub311\ud130\uc758 \ubaa8\ub4e0 Casbin import\uac00 v3\ub97c \uc0ac\uc6a9\ud558\ub294\uc9c0 \ud655\uc778\ud558\uc138\uc694:\\n\\n```go\\nimport (\\n    \\"github.com/casbin/casbin/v3\\"\\n    \\"github.com/casbin/casbin/v3/persist\\"\\n)\\n```\\n\\n## FAQ\\n\\n### Q: v2\ub294 \uc5ec\uc804\ud788 \uc720\uc9c0\ubcf4\uc218\ub418\ub098\uc694? {#q-is-v2-still-maintained}\\n\\n\ud604\uc7ac \uc2dc\uc810\uc5d0\uc11c v2\ub294 \uc911\uc694\ud55c \ubc84\uadf8 \uc218\uc815\uc744 \ubc1b\uace0 \uc788\uc9c0\ub9cc, \uc0c8\ub85c\uc6b4 \uae30\ub2a5\uc740 v3\uc6a9\uc73c\ub85c \uac1c\ubc1c\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ud5a5\ud6c4 6-12\uac1c\uc6d4 \ub0b4\uc5d0 \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc744 \uacc4\ud68d\ud558\uc138\uc694.\\n\\n### Q: \uc77c\ubd80 \uc11c\ube44\uc2a4\ub294 v2\ub97c \uc0ac\uc6a9\ud558\uace0 \ub098\uba38\uc9c0\ub294 v3\ub97c \uc0ac\uc6a9\ud558\uba74\uc11c \uc810\uc9c4\uc801\uc73c\ub85c \ub9c8\uc774\uadf8\ub808\uc774\uc158\ud560 \uc218 \uc788\ub098\uc694? {#q-can-i-gradually-migrate-by-having-some-services-on-v2-and-others-on-v3}\\n\\n\ub124! \ub3d9\uc77c\ud55c \uc815\ucc45 \ub370\uc774\ud130\ubca0\uc774\uc2a4\ub97c \uacf5\uc720\ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub294 v3\uc5d0\uc11c \ubcc0\uacbd \uc0ac\ud56d\uc774 \ucd5c\uc18c\ud654\ub418\uc5c8\uae30 \ub54c\ubb38\uc5d0 \uc5bb\uc744 \uc218 \uc788\ub294 \uc774\uc810 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4.\\n\\n### Q: \uc81c \ubbf8\ub4e4\uc6e8\uc5b4(Gin, Echo, Fiber \ub4f1)\ub3c4 \uc791\ub3d9\ud558\ub098\uc694? {#q-will-my-middleware-gin-echo-fiber-etc-work}\\n\\n\ubbf8\ub4e4\uc6e8\uc5b4\uac00 Enforcer\uc640 \ub3d9\uc77c\ud55c \uc8fc\uc694 \ubc84\uc804\uc744 import\ud558\ub294 \uacbd\uc6b0\uc5d0\ub9cc \uc791\ub3d9\ud569\ub2c8\ub2e4. \ubbf8\ub4e4\uc6e8\uc5b4\uc758 `go.mod` \ud30c\uc77c\uc744 \ud655\uc778\ud558\uc138\uc694. \ub9cc\uc57d \uc5ec\uc804\ud788 v2\ub77c\uba74, \uc704\uc5d0\uc11c \ubcf4\uc5ec\uc900 \uac83\uacfc \uac19\uc774 \uc790\uccb4 \ud578\ub4e4\ub7ec\uc5d0\uc11c `Enforce()`\ub97c \ud638\ucd9c\ud558\uc2ed\uc2dc\uc624.\\n\\n### Q: .conf \ubaa8\ub378 \ud30c\uc77c\uc744 \uc5c5\ub370\uc774\ud2b8\ud574\uc57c \ud558\ub098\uc694? {#q-do-i-need-to-update-my-conf-model-files}\\n\\n\uc544\ub2c8\uc694. \ubaa8\ub378 \ud30c\uc77c \uad6c\ubb38\uc740 \ubcc0\uacbd\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.\\n\\n### Q: .csv \uc815\ucc45 \ud30c\uc77c\uc744 \uc5c5\ub370\uc774\ud2b8\ud574\uc57c \ud558\ub098\uc694? {#q-do-i-need-to-update-my-csv-policy-files}\\n\\n\uc544\ub2c8\uc694. \uc815\ucc45 \ud30c\uc77c \ud615\uc2dd\uc740 \ubcc0\uacbd\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.\\n\\n### Q: WatcherEx, FilteredAdapter \ubc0f \uae30\ud0c0 \uc778\ud130\ud398\uc774\uc2a4\ub294 \uc5b4\ub5bb\uac8c \ub418\ub098\uc694? {#q-what-about-watcherex-filteredadapter-and-other-interfaces}\\n\\n\ubaa8\ub4e0 \uc778\ud130\ud398\uc774\uc2a4\ub294 \ubcc0\uacbd\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \ucf54\ub4dc\uac00 \uc774\ub7ec\ud55c \uc778\ud130\ud398\uc774\uc2a4\ub97c \uad6c\ud604\ud558\uace0 \uc788\ub2e4\uba74 (import \uacbd\ub85c \ubcc0\uacbd \uc678\uc5d0\ub294) \uc218\uc815\ud560 \ud544\uc694\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n### Q: \uc131\ub2a5 \uc601\ud5a5\uc740 \uc5b4\ub5a4\uac00\uc694? {#q-performance-impact}\\n\\n\uc5c6\uc2b5\ub2c8\ub2e4. v3\uc740 v2\uc640 \ub3d9\uc77c\ud55c \ud3c9\uac00 \uc5d4\uc9c4\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.\\n\\n### Q: Go 1.16\uc73c\ub85c v3\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub098\uc694? {#q-can-i-use-v3-with-go-116}\\n\\nCasbin v3 \uc800\uc7a5\uc18c\uc758 go.mod \ud30c\uc77c\uc744 \ud655\uc778\ud558\uc5ec \uc9c0\uc6d0\ub418\ub294 \ucd5c\uc18c Go \ubc84\uc804\uc744 \ud655\uc778\ud558\uc138\uc694. \uc77c\ubc18\uc801\uc73c\ub85c \ucd5c\uc2e0 \uc548\uc815\ud654 \ubc84\uc804\uc758 Go \uc0ac\uc6a9\uc744 \uad8c\uc7a5\ud569\ub2c8\ub2e4.\\n\\n\uc131\uacf5\uc801\uc778 \uc5c5\uadf8\ub808\uc774\ub4dc\ub97c \uae30\uc6d0\ud569\ub2c8\ub2e4!"},{"id":"casbin-2025-ai-agent-era","metadata":{"permalink":"/ko/blog/casbin-2025-ai-agent-era","editUrl":"https://github.com/apache/casbin-website/edit/master/i18n/ko/docusaurus-plugin-content-blog/2025-12-11-casbin-2025-ai-agent-era.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2025-12-11-casbin-2025-ai-agent-era.md","title":"2025\ub144 Casbin: AI \uc5d0\uc774\uc804\ud2b8 \uc2dc\ub300\uc758 \uc778\uac00","description":"2024\ub144\uc740 AI \uc5d0\uc774\uc804\ud2b8\uac00 \ub370\ubaa8\uc5d0\uc11c \ud504\ub85c\ub355\uc158\uc73c\ub85c \uc774\ub3d9\ud55c \ud574\uc600\uc2b5\ub2c8\ub2e4. Model Context Protocol(MCP)\uc740 Google, OpenAI, Microsoft \ubc0f \uae30\ud0c0 \uc5ec\ub7ec \uae30\uc5c5\uc5d0 \uc758\ud574 \ucc44\ud0dd\ub418\uc5c8\uc73c\uba70, \uc560\ud50c\ub9ac\ucf00\uc774\uc158\uc774 \uc678\ubd80 \uc11c\ube44\uc2a4\uc640 \ud1b5\uc2e0\ud558\ub294 \ubc29\uc2dd\uc774 \ubcc0\ud654\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \ubcc0\ud654\ub294 \uc6b0\ub9ac\uac00 Casbin\uc5d0\uc11c \uc9c0\uc18d\uc801\uc73c\ub85c\u53d6\u308a\u7d44\uace0 \uc788\ub294 \uc0c8\ub85c\uc6b4 \uc77c\ub828\uc758 \uc778\uac00 \uacfc\uc81c\ub97c \uac00\uc838\uc635\ub2c8\ub2e4.","date":"2025-12-11T00:00:00.000Z","tags":[{"inline":true,"label":"casbin","permalink":"/ko/blog/tags/casbin"},{"inline":true,"label":"roadmap","permalink":"/ko/blog/tags/roadmap"},{"inline":true,"label":"AI","permalink":"/ko/blog/tags/ai"},{"inline":true,"label":"MCP","permalink":"/ko/blog/tags/mcp"},{"inline":true,"label":"edge-computing","permalink":"/ko/blog/tags/edge-computing"},{"inline":true,"label":"LLM","permalink":"/ko/blog/tags/llm"}],"readingTime":3.75,"hasTruncateMarker":true,"authors":[{"name":"Yang Luo","title":"Creator of Casbin","url":"https://github.com/hsluoyz","imageURL":"/ko/img/authors/hsluoyz.png","key":"hsluoyz","page":null}],"frontMatter":{"title":"2025\ub144 Casbin: AI \uc5d0\uc774\uc804\ud2b8 \uc2dc\ub300\uc758 \uc778\uac00","slug":"casbin-2025-ai-agent-era","authors":["hsluoyz"],"tags":["casbin","roadmap","AI","MCP","edge-computing","LLM"]},"unlisted":false,"prevItem":{"title":"Casbin (Go) v2\uc5d0\uc11c v3\ub85c \uc5c5\uadf8\ub808\uc774\ub4dc: \uc644\uc804\ud55c \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uac00\uc774\ub4dc","permalink":"/ko/blog/upgrading-casbin-go-v2-to-v3"},"nextItem":{"title":"Casbin \ub9e4\uce6d \ub3d9\uc791 \uc0c1\uc138 \uc774\ud574","permalink":"/ko/blog/2023/12/08/understanding-casbin-matching-in-detail"}},"content":"2024\ub144\uc740 AI \uc5d0\uc774\uc804\ud2b8\uac00 \ub370\ubaa8\uc5d0\uc11c \ud504\ub85c\ub355\uc158\uc73c\ub85c \uc774\ub3d9\ud55c \ud574\uc600\uc2b5\ub2c8\ub2e4. Model Context Protocol(MCP)\uc740 Google, OpenAI, Microsoft \ubc0f \uae30\ud0c0 \uc5ec\ub7ec \uae30\uc5c5\uc5d0 \uc758\ud574 \ucc44\ud0dd\ub418\uc5c8\uc73c\uba70, \uc560\ud50c\ub9ac\ucf00\uc774\uc158\uc774 \uc678\ubd80 \uc11c\ube44\uc2a4\uc640 \ud1b5\uc2e0\ud558\ub294 \ubc29\uc2dd\uc774 \ubcc0\ud654\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \ubcc0\ud654\ub294 \uc6b0\ub9ac\uac00 Casbin\uc5d0\uc11c \uc9c0\uc18d\uc801\uc73c\ub85c\u53d6\u308a\u7d44\uace0 \uc788\ub294 \uc0c8\ub85c\uc6b4 \uc77c\ub828\uc758 \uc778\uac00 \uacfc\uc81c\ub97c \uac00\uc838\uc635\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## \uc138\uc0c1\uc774 \ubcc0\ud588\uc2b5\ub2c8\ub2e4 {#the-world-has-changed}\\n\\n2017\ub144\uc5d0 Casbin\uc744 \uc2dc\uc791\ud588\uc744 \ub54c, \uc77c\ubc18\uc801\uc778 \uc778\uac00 \uc2dc\ub098\ub9ac\uc624\ub294 \ub2e8\uc21c\ud588\uc2b5\ub2c8\ub2e4. \uc0ac\uc6a9\uc790\uac00 \uc694\uccad\uc744 \ud558\uace0, \uad8c\ud55c\uc774 \uc788\ub294\uc9c0 \ud655\uc778\ud558\uba70, \ub05d\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \uc624\ub298\ub0a0\uc5d0\ub294 \uc5b4\ub5a8\uae4c\uc694? AI \uc5d0\uc774\uc804\ud2b8\uac00 \uc0ac\uc6a9\uc790\ub97c \ub300\uc2e0\ud558\uc5ec \ud589\ub3d9\ud558\uace0, \uac01\uac01 \uc790\uccb4\uc801\uc778 \ub3c4\uad6c \uad8c\ud55c\uc744 \uac00\uc9c4 \uc5ec\ub7ec MCP \uc11c\ubc84\ub97c \ud638\ucd9c\ud560 \uc218 \uc788\uc73c\uba70, \uc804\uccb4 \uacfc\uc815\uc774 \uc5d0\uc9c0\uc5d0\uc11c \ubc00\ub9ac\ucd08 \ub2e8\uc704\ub85c \ucc98\ub9ac\ub418\uc5b4\uc57c \ud569\ub2c8\ub2e4.\\n\\nMCP \uc0ac\uc591\uc740 \uc774\uc81c MCP \uc11c\ubc84\ub97c OAuth 2.0 \ub9ac\uc18c\uc2a4 \uc11c\ubc84\ub85c \ubd84\ub958\ud569\ub2c8\ub2e4(2025\ub144 6\uc6d4 \uc5c5\ub370\uc774\ud2b8). `mcp:tools:weather` \ub610\ub294 `mcp:resources:customer-data:read`\uc640 \uac19\uc740 \uc138\ubd84\ud654\ub41c \ubc94\uc704\ub97c \ud3ec\ud568\ud569\ub2c8\ub2e4. \uc774\ub294 Casbin\uc774 \uc124\uacc4\ub41c \uc815\ubc00\ud55c \uad8c\ud55c \ubaa8\ub378\uc774\uc9c0\ub9cc, MCP \ubc0f OAuth\uc640\uc758 \ud1b5\ud569\uc5d0\ub294 \uc544\uc9c1 \ub354 \ub9ce\uc740 \uc791\uc5c5\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n## \uc6b0\ub9ac\uac00 \uc9c4\ud589 \uc911\uc778 \uc791\uc5c5 {#what-were-working-on}\\n\\n### MCP \uc11c\ubc84 \uc778\uac00 {#mcp-server-authorization}\\n\\n\uc774\ub294 \uc6b0\ub9ac\uc758 \uc8fc\uc694 \uad00\uc2ec \ubd84\uc57c \uc911 \ud558\ub098\uc785\ub2c8\ub2e4. AI \uc5d0\uc774\uc804\ud2b8\uac00 MCP \uc11c\ubc84\ub97c \ud638\ucd9c\ud560 \ub54c, \uc11c\ubc84\ub294 \ub2e4\uc74c\uc744 \uacb0\uc815\ud574\uc57c \ud569\ub2c8\ub2e4. \uc774 \uc5d0\uc774\uc804\ud2b8\uac00 \uc774 \uc0ac\uc6a9\uc790\ub97c \ub300\uc2e0\ud558\uc5ec \uc774 \ub9e4\uac1c\ubcc0\uc218\ub85c \uc774 \ub3c4\uad6c\ub97c \uc2e4\ud589\ud560 \uc218 \uc788\ub294\uac00?\\n\\n\uc804\ud1b5\uc801\uc778 RBAC\ub9cc\uc73c\ub85c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. ABAC\uacfc \uac19\uc740 \uac83\uc774 \ud544\uc694\ud569\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \u201c\uc774 \uc5d0\uc774\uc804\ud2b8\uac00 \uc5c5\ubb34 \uc2dc\uac04 \ub3d9\uc548 Alice\uc758 \uc9c0\uc5ed \uace0\uac1d \ub370\uc774\ud130\uc5d0 \uc811\uadfc\ud560 \uc218 \uc788\ub294\uac00?\u201d Casbin\uc758 \uc815\ucc45 \ubaa8\ub378\uc774 \uc774\ub7ec\ud55c \uc81c\uc57d \uc870\uac74\uc744 \uc5b4\ub5bb\uac8c \ud45c\ud604\ud560 \uc218 \uc788\ub294\uc9c0 \ud0d0\uc0c9\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\ub09c\uc810\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. MCP \uc11c\ubc84\ub294 \ub9e4\uc6b0 \ube60\ub974\uac8c \uacb0\uc815\uc744 \ub0b4\ub824\uc57c \ud569\ub2c8\ub2e4. \ubcc4\ub3c4\uc758 \uc778\uac00 \uc11c\ube44\uc2a4\ub97c \ud638\ucd9c\ud558\ub294 \ub300\uc2e0, MCP \uc11c\ubc84 \ud504\ub85c\uc138\uc2a4 \ub0b4\uc5d0\uc11c \uacbd\ub7c9 \uc815\ucc45 \ud3c9\uac00\ub97c \uc218\ud589\ud558\ub294 \ubc29\uc548\uc744 \uac80\ud1a0\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \uc5e3\uc9c0 \uc6b0\uc120 \uc778\uac00 {#edge-first-authorization}\\n\\nCloudflare Workers, Deno Deploy, Vercel Edge Functions \ub4f1 \uc5e3\uc9c0 \ucef4\ud4e8\ud305 \ubd84\uc57c\uac00 \uae09\uc131\uc7a5\ud588\uc2b5\ub2c8\ub2e4. 2025\ub144\uc5d0\ub294 50ms \ubbf8\ub9cc\uc758 \uc751\ub2f5 \uc2dc\uac04\uc774 \uae30\ubcf8 \uc694\uad6c \uc0ac\ud56d\uc774 \ub418\uc5c8\uc73c\uba70, \uc911\uc559 \uc11c\ubc84\ub85c\uc758 \uc778\uac00 \uac80\uc0ac\uc5d0 100ms\ub97c \ud560\uc560\ud560 \uc5ec\uc720\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\ub294 Casbin\uc758 \uc791\ub3d9 \ubc29\uc2dd\uc744 \ub2e4\ub974\uac8c \uc0dd\uac01\ud558\ub3c4\ub85d \uc6b0\ub9ac\ub97c \ucd94\ub3d9\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc815\ucc45\uc744 WebAssembly\ub85c \ucef4\ud30c\uc77c\ud558\uc5ec V8 \uaca9\ub9ac\uc5d0 \uc9c1\uc811 \uc2e4\ud589\ud560 \uc218 \uc788\uc744\uae4c\uc694? \uc77c\uad00\uc131\uc744 \uc720\uc9c0\ud558\uba74\uc11c \uc5e3\uc9c0\uc5d0\uc11c \uc2a4\ub9c8\ud2b8 \uc815\ucc45 \uce90\uc2f1\uc744 \uc218\ud589\ud560 \uc218 \uc788\uc744\uae4c\uc694? \uc774\ub7ec\ud55c \ubb38\uc81c\ub294 \uc5b4\ub824\uc6b4 \uacfc\uc81c\uc774\uba70, \uc6b0\ub9ac\ub294 \uc544\uc9c1 \ubaa8\ub4e0 \ub2f5\uc744 \uac00\uc9c0\uace0 \uc788\uc9c0 \uc54a\uc9c0\ub9cc, \uc774\uac83\uc774 \ud5a5\ud6c4 \ubc29\ud5a5\uc785\ub2c8\ub2e4.\\n\\n\ud2b9\ud788 Cloudflare Workers \uc0dd\ud0dc\uacc4\uc5d0 \uad00\uc2ec\uc774 \ub9ce\uc2b5\ub2c8\ub2e4. \uadf8\ub4e4\uc740 \ub0b4\uc7a5 OAuth \uc9c0\uc6d0\uc744 \uac16\ucd98 MCP \uc11c\ubc84\uc6a9 \uc804\uccb4 \ud50c\ub7ab\ud3fc\uc744 \uad6c\ucd95\ud588\uc2b5\ub2c8\ub2e4. \uadf8\uacf3\uc5d0\uc11c\uc758 \ub124\uc774\ud2f0\ube0c Casbin \ud1b5\ud569\uc740 \uac15\ub825\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### RAG \ud30c\uc774\ud504\ub77c\uc778 \uc778\uac00 {#rag-pipeline-authorization}\\n\\n\ubc18\ubcf5\ub418\ub294 \uc8fc\uc81c\uc785\ub2c8\ub2e4. LLM\uc774 \ub0b4\ubd80 \ubb38\uc11c\uc5d0 \uc811\uadfc\ud574\uc57c \ud558\uc9c0\ub9cc \uac01 \uc0ac\uc6a9\uc790\ub294 \ud5c8\uc6a9\ub41c \ubb38\uc11c\ub9cc \ubcfc \uc218 \uc788\uc5b4\uc57c \ud558\ub294 RAG \uc2dc\uc2a4\ud15c\uc744 \uad6c\ucd95\ud558\ub294 \ud68c\uc0ac\ub4e4\uc774 \uc788\uc2b5\ub2c8\ub2e4.\\n\\nOWASP Top 10 for LLM Applications 2025\ub294 \u201c\ubbfc\uac10 \uc815\ubcf4 \ub178\ucd9c\u201d\uc744 \uc8fc\uc694 \uc704\ud5d8\uc73c\ub85c \ubaa9\ub85d\ud654\ud588\uc2b5\ub2c8\ub2e4. \ud574\uacb0\ucc45\uc740 \ucd9c\ub825\ub9cc \ud544\ud130\ub9c1\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, LLM\uc774 \uc0ac\uc6a9\uc790\uac00 \uc811\uadfc \uad8c\ud55c\uc774 \uc5c6\ub294 \ubb38\uc11c\ub97c \uc808\ub300 \uac80\uc0c9\ud558\uc9c0 \uc54a\ub3c4\ub85d \ubcf4\uc7a5\ud558\ub294 \uac83\uc785\ub2c8\ub2e4.\\n\\n\ub530\ub77c\uc11c \uc778\uac00\ub294 \ubca1\ud130 \uc2a4\ud1a0\uc5b4 \ucffc\ub9ac \uc218\uc900\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc838\uc57c \ud569\ub2c8\ub2e4. Casbin \uc815\ucc45\uc744 \ubca1\ud130 DB\uc758 \uba54\ud0c0\ub370\uc774\ud130 \ud544\ud130\ub85c \ubcc0\ud658\ud558\ub294 \uac83\uc744 \uac80\ud1a0\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc989, \uad8c\ud55c \uac80\uc0ac\uac00 \uac80\uc0c9\uc73c\ub85c \ud478\uc2dc\ub2e4\uc6b4\ub418\ub294 WHERE \uc808\uc774 \ub418\ub294 \uac83\uc785\ub2c8\ub2e4.\\n\\n### \uba40\ud2f0 \uc5d0\uc774\uc804\ud2b8 \uc2dc\ub098\ub9ac\uc624 {#multi-agent-scenarios}\\n\\n\uccb4\uc778\uc5d0 \uc5ec\ub7ec \uc5d0\uc774\uc804\ud2b8\uac00 \uc874\uc7ac\ud558\ub294 \uacbd\uc6b0(\uc608: \ucf54\ub529 \uc5d0\uc774\uc804\ud2b8 \u2192 \ubc30\ud3ec \uc5d0\uc774\uc804\ud2b8 \u2192 \ubaa8\ub2c8\ud130\ub9c1 \uc5d0\uc774\uc804\ud2b8), \uad8c\ud55c \uc704\uc784\uc740 \uae4c\ub2e4\ub86d\uc2b5\ub2c8\ub2e4. \uac01 \uc5d0\uc774\uc804\ud2b8\ub294 \ub2e4\ub978 \uae30\ub2a5\uc744 \uac00\uc9c8 \uc218 \uc788\uc73c\uba70, \uc804\uccb4 \uccb4\uc778\uc744 \ucd94\uc801\ud574\uc57c \ud569\ub2c8\ub2e4.\\n\\nOAuth\uc758 On-Behalf-Of(OBO) \ud750\ub984\uc740 \uc774 \ubd80\ubd84 \uc911 \uc77c\ubd80\ub97c \ub2e4\ub8e8\uc9c0\ub9cc, \u201c\uc5d0\uc774\uc804\ud2b8 B\uac00 \uc5d0\uc774\uc804\ud2b8 A\ub97c \ub300\uc2e0\ud558\uc5ec \uc0ac\uc6a9\uc790 alice\ub97c \uc704\ud574 X\ub97c \uc218\ud589\ud560 \uc218 \uc788\ub294\uac00?\u201d\ub77c\ub294 \ub85c\uc9c1\uc5d0\ub294 \uba85\ud655\ud55c \ubaa8\ub378\uc774 \ud544\uc694\ud569\ub2c8\ub2e4. Casbin\uc758 \uc5ed\ud560 \uacc4\uce35 \uad6c\uc870 \ubc0f \ub3c4\uba54\uc778 RBAC\uc740 \uc5d0\uc774\uc804\ud2b8 \uacc4\uce35 \uad6c\uc870\ub85c \ud655\uc7a5\ub420 \uc218 \uc788\uc73c\uba70, \uc6b0\ub9ac\ub294 \uadf8 \uc758\ubbf8\ub860\uc801 \ubd80\ubd84\uc744 \uc815\ub9ac\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## \uc804\ud1b5\uc801\uc778 \ub85c\ub4dc\ub9f5 \ud56d\ubaa9 {#the-traditional-roadmap-stuff}\\n\\n\ubb3c\ub860, \uc6b0\ub9ac\ub294 \uae30\ubcf8 \uc0ac\ud56d\uc744 \ud3ec\uae30\ud558\uc9c0 \uc54a\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc6b0\ub9ac \ubaa9\ub85d\uc5d0 \uc788\ub294 \uba87 \uac00\uc9c0 \uc2e4\uc6a9\uc801\uc778 \uc0ac\ud56d\ub4e4:\\n\\n**\uc5b8\uc5b4 \uad6c\ud604 \ub530\ub77c\uc7a1\uae30** - SwiftCasbin \ubc0f Lua-Casbin\uc740 \uc5ec\uc804\ud788 Go \ubc0f Node.js \ubc84\uc804\ubcf4\ub2e4 \uae30\ub2a5\uc774 \ub4a4\ucc98\uc838 \uc788\uc2b5\ub2c8\ub2e4. `in` \uc5f0\uc0b0\uc790, WatcherEx, `g` \ud568\uc218\ub97c \uc704\ud55c \ub354 \ub098\uc740 \uce90\uc2f1 \ub4f1\uc740 \ubaa8\ub4e0 \uacf3\uc5d0\uc11c \uc77c\uad00\uc131\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n**\uc0c8\ub85c\uc6b4 \ud504\ub808\uc784\uc6cc\ud06c \ubbf8\ub4e4\uc6e8\uc5b4** - go-zero\uac00 \ubc18\ubcf5\uc801\uc73c\ub85c \uc694\uccad\ub418\uc5c8\uc2b5\ub2c8\ub2e4. Rust\uc6a9 Poem\uc774 \uc778\uae30\ub97c \uc5bb\uace0 \uc788\uc2b5\ub2c8\ub2e4. Java\uc6a9 Play Framework\ub294 \uc624\ub7ab\ub3d9\uc548 \uc704\uc2dc\ub9ac\uc2a4\ud2b8\uc5d0 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n**\uc131\ub2a5 \uc791\uc5c5** - \uc774\ub7ec\ud55c \uc0c8\ub85c\uc6b4 \uc0ac\uc6a9 \uc0ac\ub840\ub97c \uc704\ud574 \uc815\ucc45\uc774 \ub354 \ubcf5\uc7a1\ud574\uc9d0\uc5d0 \ub530\ub77c \ud3c9\uac00 \uc18d\ub3c4\uac00 \ub354 \uc911\uc694\ud574\uc9d1\ub2c8\ub2e4. \ubaa8\ub4e0 \uad6c\ud604 \uc804\ubc18\uc5d0\uc11c \ub354 \ub098\uc740 \ubca4\uce58\ub9c8\ud0b9, \ud504\ub85c\ud30c\uc77c\ub9c1 \ubc0f \ucd5c\uc801\ud654\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n## \uc544\uc9c1 \ubaa8\ub974\ub294 \uac83\ub4e4 {#what-we-dont-know-yet}\\n\\nAI \uc5d0\uc774\uc804\ud2b8 \uc778\uac00 \ubd84\uc57c\ub294 \ube60\ub974\uac8c \ubcc0\ud654\ud558\uace0 \uc788\uc73c\uba70, \uc6b0\ub9ac\ub294 \uc9c4\ud589\ud558\uba74\uc11c \ud559\uc2b5\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ubbf8\ud574\uacb0 \uacfc\uc81c:\\n\\n- Casbin\uc5d0 \\"\uc5d0\uc774\uc804\ud2b8 \uc2dd\ubcc4\uc790\\"\uc640 \\"\uc0ac\uc6a9\uc790 \uc2dd\ubcc4\uc790\\"\ub97c \uc704\ud55c 1\uae09 \uc6d0\uc2dc \uc790\ub8cc\ud615(first-class primitives)\uc744 \uc81c\uacf5\ud574\uc57c \ud560\uae4c\uc694?\\n- MCP\ub97c \ud1b5\ud574 \ub3d9\uc801\uc73c\ub85c \ubc1c\uacac\ub41c \ub3c4\uad6c\uc5d0 \ub300\ud55c \uc778\uac00\ub294 \uc5b4\ub5bb\uac8c \ucc98\ub9ac\ud558\ub098\uc694?\\n- \uc815\ucc45\uc774 \uc2e4\uc2dc\uac04 \ucee8\ud14d\uc2a4\ud2b8\uc5d0 \uc758\uc874\ud560 \uc218 \uc788\uc744 \ub54c \uc62c\ubc14\ub978 \uce90\uc2f1 \uc804\ub7b5\uc740 \ubb34\uc5c7\uc778\uac00\uc694?\\n\\n\uc774 \ubd84\uc57c\uc5d0\uc11c \uac1c\ubc1c \uc911\uc774\uba70 \uc778\uac00 \uad00\ub828 \ubb38\uc81c\ub97c \uacaa\uace0 \uc788\ub2e4\uba74, \uc5ec\ub7ec\ubd84\uc758 \uc758\uacac\uc744 \ub4e3\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \ucd5c\uace0\uc758 \uae30\ub2a5\uc740 \uc2e4\uc81c \uc0ac\uc6a9 \uc0ac\ub840\uc5d0\uc11c \ub098\uc635\ub2c8\ub2e4.\\n\\n## \ucc38\uc5ec\ud558\uae30 {#getting-involved}\\n\\n\uc800\ud76c\ub294 \uc218\ub144\uac04 GSoC(Google Summer of Code) \ub2e8\uccb4\ub85c \ud65c\ub3d9\ud574 \uc654\uc73c\uba70, \uc774\ub7ec\ud55c AI \uad00\ub828 \uc8fc\uc81c\ub294 \uc5ec\ub984 \ud504\ub85c\uc81d\ud2b8\ub85c \uc801\ud569\ud569\ub2c8\ub2e4. GSoC\ub97c \uae30\ub2e4\ub9b4 \ud544\uc694\ub294 \uc5c6\uc2b5\ub2c8\ub2e4\u2014\ud765\ubbf8\ub86d\ub2e4\uba74 Discord\ub85c \uc5f0\ub77d\ud558\uac70\ub098 GitHub\uc5d0 \uc774\uc288\ub97c \uc5f4\uc5b4 \uc8fc\uc138\uc694.\\n\\n\uc55e\uc73c\ub85c \uba87 \ub144\uac04 \uc778\uac00 \ubd84\uc57c\ub294 \uaca9\ub3d9\uae30\uac00 \ub420 \uac83\uc785\ub2c8\ub2e4. \ubb38\uc81c\ub294 \ub354 \uc5b4\ub824\uc6cc\uc9c0\uc9c0\ub9cc, \ub3d9\uc2dc\uc5d0 \ub354 \ud765\ubbf8\ub85c\uc6cc\uc9d1\ub2c8\ub2e4. \ud568\uaed8 \ud574\uacb0\ucc45\uc744 \ucc3e\uc544\ub098\uac08 \uac83\uc744 \uae30\ub300\ud569\ub2c8\ub2e4."},{"id":"/2023/12/08/understanding-casbin-matching-in-detail","metadata":{"permalink":"/ko/blog/2023/12/08/understanding-casbin-matching-in-detail","editUrl":"https://github.com/apache/casbin-website/edit/master/i18n/ko/docusaurus-plugin-content-blog/2023-12-08-understanding-casbin-matching-in-detail.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2023-12-08-understanding-casbin-matching-in-detail.md","title":"Casbin \ub9e4\uce6d \ub3d9\uc791 \uc0c1\uc138 \uc774\ud574","description":"\uc774 \uae00\uc740 Casbin \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc0ac\uc6a9\ud558\uc5ec RBAC\ub97c \uc124\uacc4\ud558\uace0 \uad6c\ud604\ud558\ub294 \ubc29\ubc95\uc744 \uc124\uba85\ud569\ub2c8\ub2e4.","date":"2023-12-08T00:00:00.000Z","tags":[],"readingTime":5.41,"hasTruncateMarker":true,"authors":[{"name":"Aravinda Kumar","url":"https://github.com/aravindarc","imageURL":"/ko/img/authors/aravindarc.png","key":"aravindarc","page":null}],"frontMatter":{"title":"Casbin \ub9e4\uce6d \ub3d9\uc791 \uc0c1\uc138 \uc774\ud574","authors":["aravindarc"]},"unlisted":false,"prevItem":{"title":"2025\ub144 Casbin: AI \uc5d0\uc774\uc804\ud2b8 \uc2dc\ub300\uc758 \uc778\uac00","permalink":"/ko/blog/casbin-2025-ai-agent-era"},"nextItem":{"title":"Casbin\uc744 \uc0ac\uc6a9\ud558\uc5ec APISIX\uc5d0\uc11c \uc778\uc99d \ucc98\ub9ac","permalink":"/ko/blog/2021/08/19/apisix-casbin-authorization"}},"content":"\uc774 \uae00\uc740 [Casbin](https://casbin.apache.org/) \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc0ac\uc6a9\ud558\uc5ec RBAC\ub97c \uc124\uacc4\ud558\uace0 \uad6c\ud604\ud558\ub294 \ubc29\ubc95\uc744 \uc124\uba85\ud569\ub2c8\ub2e4.\\n\ub9ac\uc18c\uc2a4 \uacc4\uce35 \uad6c\uc870\uc640 \uad8c\ud55c\uc744 \uc0c1\uc18d\ud558\ub294 \uc5ed\ud560\uc774 \uc788\ub294 SaaS \ud50c\ub7ab\ud3fc\uc758 \uacbd\uc6b0, Casbin\uc740 \uc131\ub2a5\uc774 \uc88b\uc740 \uc635\uc158\uc785\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n## RBAC \uc18c\uac1c {#introduction-to-rbac}\\n\\nRBAC\uc740 \uc0ac\uc6a9\uc790\uac00 \ubcf4\uc720\ud55c \uc5ed\ud560\uc5d0 \uae30\ubc18\ud558\uc5ec \uc811\uadfc\uc744 \uc81c\ud55c\ud569\ub2c8\ub2e4. **\uacc4\uce35\uc801**\\nRBAC\uc774 \uc5b4\ub5bb\uac8c \uc791\ub3d9\ud558\ub294\uc9c0 \ubcf4\uae30 \uc704\ud574 Azure\uc758 RBAC\uc744 \uc0b4\ud3b4\ubcf8 \ud6c4 Casbin\uc5d0\uc11c \uc720\uc0ac\ud55c \uac83\uc744 \uad6c\ud604\ud569\ub2c8\ub2e4.\\n\\n## **Azure**\uc758 \uacc4\uce35\uc801 **RBAC** {#azures-hierarchical-rbac}\\n\\n![Azure Hierarchy](/img/blog/azure-scope-levels.png)\\n\\n**Azure**\uc5d0\uc11c\ub294 **Owner** \uc5ed\ud560\uc774 \ub2e4\uc591\ud55c \ubc94\uc704(scope)\uc5d0 \uc801\uc6a9\ub429\ub2c8\ub2e4. \uad6c\ub3c5(subscription) \uc218\uc900\uc5d0\uc11c **Owner** \uad8c\ud55c\uc744 \uac00\uc9c0\uace0 \uc788\ub2e4\uba74, \ud574\ub2f9 \uad6c\ub3c5 \ud558\uc704\uc758 \ubaa8\ub4e0 \ub9ac\uc18c\uc2a4 \uadf8\ub8f9 \ubc0f \ub9ac\uc18c\uc2a4\uc5d0 \ub300\ud55c Owner \uad8c\ud55c\uc744 \uac16\uac8c \ub429\ub2c8\ub2e4. \ub9ac\uc18c\uc2a4 \uadf8\ub8f9 \uc218\uc900\uc5d0\uc11c Owner \uad8c\ud55c\uc744 \uac00\uc9c0\uace0 \uc788\ub2e4\uba74, \ud574\ub2f9 \uadf8\ub8f9 \ub0b4\uc758 \ubaa8\ub4e0 \ub9ac\uc18c\uc2a4\uc5d0 \ub300\ud55c Owner \uad8c\ud55c\uc744 \uac16\uac8c \ub429\ub2c8\ub2e4.\\n\\n\uc544\ub798 \uc774\ubbf8\uc9c0\ub294 \uad6c\ub3c5 \uc218\uc900\uc758 Owner \uc811\uadfc \uad8c\ud55c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4. ![Subscription Owner](/img/tutorial/subscription-owner.png)\\n\\n\ud574\ub2f9 \uad6c\ub3c5 \ud558\uc704\uc758 \ub9ac\uc18c\uc2a4 \uadf8\ub8f9\uc5d0 \ub300\ud55c IAM(Identity and Access Management)\uc744 \ud655\uc778\ud558\uba74 \uc0c1\uc18d\ub41c Owner \uc811\uadfc \uad8c\ud55c\uc744 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. ![RG Owner](/img/tutorial/rg-owner.png)\\n\\n\uc774\uac83\uc774 **Azure**\uc758 RBAC\uac00 \uacc4\uce35\uc801\uc778 \ubc29\uc2dd\uc785\ub2c8\ub2e4. \ub9ce\uc740 \uc2dc\uc2a4\ud15c\uc774 \uc720\uc0ac\ud55c \uacc4\uce35 \uad6c\uc870\ub97c \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uc774 \ud29c\ud1a0\ub9ac\uc5bc\uc5d0\uc11c\ub294 Casbin\uc73c\ub85c \ube44\uad50 \uac00\ub2a5\ud55c \ubaa8\ub378\uc744 \uad6c\ud604\ud569\ub2c8\ub2e4.\\n\\n## Casbin \uc791\ub3d9 \ubc29\uc2dd {#how-casbin-works}\\n\\nCasbin\uc758 \uad6c\uc131 \uc694\uc18c(request, policy, matcher, effect)\ub97c \uc774\ud574\ud558\uba74 RBAC \ubaa8\ub378\uc744 \uc124\uacc4\ud558\uace0 \uc870\uc815\ud558\uae30\uac00 \ub354 \uc26c\uc6cc\uc9d1\ub2c8\ub2e4.\\n\\n## ACL\uc774\ub780 \ubb34\uc5c7\uc778\uac00? {#what-is-acl}\\n\\n**ACL (Access Control List)**\uc740 \uc0ac\uc6a9\uc790\ub97c \uc791\uc5c5(action)\uc5d0, \uc791\uc5c5\uc744 \ub9ac\uc18c\uc2a4\uc5d0 \ub9e4\ud551\ud569\ub2c8\ub2e4.\\n\\n### **Model** \uc815\uc758 {#model-definition}\\n\\n\ucd5c\uc18c\ud654\ub41c ACL \ubaa8\ub378:\\n\\n```toml\\n[request_definition]\\nr = sub, act, obj\\n\\n[policy_definition]\\np = sub, act, obj\\n\\n[policy_effect]\\ne = some(where (p.eft == allow))\\n\\n[matchers]\\nm = r.sub == p.sub && r.obj == p.obj && r.act == p.act\\n```\\n\\n1. **request_definition** \u2014 \uc694\uccad \ud615\uc2dd\uc744 \uc815\uc758\ud569\ub2c8\ub2e4. \uc608: `alice, write, data1`\uc740 \\"Alice\uac00 data1\uc744 \uc4f8 \uc218 \uc788\ub294\uac00?\\"\ub77c\ub294 \uc758\ubbf8\uc785\ub2c8\ub2e4.\\n2. **policy_definition** \u2014 \uc815\ucc45 \ud615\uc2dd\uc744 \uc815\uc758\ud569\ub2c8\ub2e4. \uc608: \uc815\ucc45 `alice, write, data1`\uc740 Alice\uc5d0\uac8c data1 \uc4f0\uae30 \uad8c\ud55c\uc744 \ubd80\uc5ec\ud569\ub2c8\ub2e4.\\n3. **policy_effect** \u2014 \uc5ec\ub7ec \uc77c\uce58\ud558\ub294 \uc815\ucc45\uc774 \uacb0\ud569\ub418\ub294 \ubc29\uc2dd(\uc608: allow-override)\uc744 \uc815\uc758\ud569\ub2c8\ub2e4.\\n4. **matchers** \u2014 \ucda9\uc871\ub418\uc5b4\uc57c \ud558\ub294 \uc870\uac74: `r.sub == p.sub && r.obj == p.obj && r.act == p.act`.\\n\\n### Casbin \uc5d0\ub514\ud130\uc5d0\uc11c \uc2dc\ub3c4\ud574 \ubcf4\uae30 {#try-it-in-the-casbin-editor}\\n\\n[Casbin editor](https://casbin.org/editor)\ub97c \uc5f4\uace0 \uc704\uc758 \ubaa8\ub378\uc744 **Model** \uc5d0\ub514\ud130\uc5d0 \ubd99\uc5ec\ub123\uc73c\uc138\uc694.\\n\\n\ub2e4\uc74c \ub0b4\uc6a9\uc744 **Policy** \uc5d0\ub514\ud130\uc5d0 \ubd99\uc5ec\ub123\uc73c\uc138\uc694:\\n\\n```csv\\np, alice, read, data1\\np, bob, write, data2\\n```\\n\\n\uadf8\ub9ac\uace0 \ub2e4\uc74c \ub0b4\uc6a9\uc744 **Request** \uc5d0\ub514\ud130\uc5d0 \ubd99\uc5ec\ub123\uc73c\uc138\uc694:\\n\\n```csv\\nalice, read, data1\\n```\\n\\n\uacb0\uacfc\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4:\\n\\n```text\\ntrue\\n```\\n\\n### ACL \ubaa8\ub378, \uc815\ucc45 \ubc0f \uc694\uccad \ub9e4\uce6d\uc758 \uc2dc\uac01\uc801 \ud45c\ud604 {#visual-representation-of-the-acl-model-policy-and-request-matching}\\n\\n![acl](/img/tutorial/acl.png)\\n\\n## RBAC\uc774\ub780 \ubb34\uc5c7\uc778\uac00? {#what-is-rbac}\\n\\n**RBAC (Role-Based Access Control)**\uc740 \uc0ac\uc6a9\uc790\uc5d0\uac8c \uc5ed\ud560\uc744 \ud560\ub2f9\ud558\uba70, \uc5ed\ud560\uc740 \ub9ac\uc18c\uc2a4\uc5d0 \ub300\ud55c \uad8c\ud55c\uc744 \uac00\uc9d1\ub2c8\ub2e4. \uc694\uccad\uc740 \uc0ac\uc6a9\uc790\uc758 \uc5ed\ud560\uc774 \ub9ac\uc18c\uc2a4\uc5d0 \ub300\ud55c \uc791\uc5c5\uc744 \ud5c8\uc6a9\ud558\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.\\n\\n### **Model** \uc815\uc758 {#model-definition-1}\\n\\n\uac04\ub2e8\ud55c RBAC \ubaa8\ub378:\\n\\n```toml\\n[request_definition]\\nr = sub, act, obj\\n\\n[policy_definition]\\np = sub, act, obj\\n\\n[role_definition]\\ng = _, _\\ng2 = _, _\\n\\n[policy_effect]\\ne = some(where (p.eft == allow))\\n\\n[matchers]\\nm = r.sub == p.sub && g(p.act, r.act) && r.obj == p.obj\\n```\\n\\n1. **role_definition** \u2014 \uadf8\ub798\ud504 \uad00\uacc4(\uc608: \uc5ed\ud560-\uc5ed\ud560 \ub610\ub294 \uc0ac\uc6a9\uc790-\uc5ed\ud560\uc744 \uc704\ud55c `g`)\ub97c \uc815\uc758\ud569\ub2c8\ub2e4. matcher\ub294 \uc774\ub97c \uc0ac\uc6a9\ud558\uc5ec \uc5ed\ud560\uacfc \uad8c\ud55c\uc744 \ud574\uc11d\ud569\ub2c8\ub2e4.\\n\\n### Casbin \uc5d0\ub514\ud130\uc5d0\uc11c \uc2dc\ub3c4\ud574 \ubcf4\uae30 {#try-it-in-the-casbin-editor-1}\\n\\n[editor](https://casbin.org/editor)\ub97c \uc5f4\uace0 \uc704\uc758 \ubaa8\ub378\uc744 \ubd99\uc5ec\ub123\uc73c\uc138\uc694.\\n\\n\ub2e4\uc74c \ub0b4\uc6a9\uc744 **Policy** \uc5d0\ub514\ud130\uc5d0 \ubd99\uc5ec\ub123\uc73c\uc138\uc694:\\n\\n```csv\\np, alice, reader, data1\\np, bob, owner, data2\\n\\ng, reader, read\\ng, owner, read\\ng, owner, write\\n```\\n\\n\uadf8\ub9ac\uace0 \ub2e4\uc74c \ub0b4\uc6a9\uc744 **Request** \uc5d0\ub514\ud130\uc5d0 \ubd99\uc5ec\ub123\uc73c\uc138\uc694:\\n\\n```csv\\nalice, read, data1\\nalice, write, data1\\nbob, write, data2\\nbob, read, data2\\nbob, write, data1\\n```\\n\\n\uacb0\uacfc\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4:\\n\\n```text\\ntrue\\nfalse\\ntrue\\ntrue\\nfalse\\n```\\n\\n### RBAC \ubaa8\ub378, \uc815\ucc45 \ubc0f \uc694\uccad \ub9e4\uce6d\uc758 \uc2dc\uac01\uc801 \ud45c\ud604 {#visual-representation-of-the-rbac-model-policy-and-request-matching}\\n\\n![rbac](/img/tutorial/rbac.png)\\n\\n**g** (\uc5ed\ud560-\uc791\uc5c5) \uad00\uacc4\ub294 \uadf8\ub798\ud504\uc785\ub2c8\ub2e4. \uc815\ucc45\uc5d0\uc11c\ub294 \uac00\uc7a5\uc790\ub9ac(edges)\ub85c \uc791\uc131\ub418\uba70, \uc608\ub97c \ub4e4\uc5b4 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4:\\n\\n```csv\\ng, reader, read\\ng, owner, read\\ng, owner, write\\n```\\n\\n:::info\\n**p**\ub294 \uc77c\ubc18\uc801\uc778 \uc815\ucc45(`==`\uc640 \ube44\uad50)\uc785\ub2c8\ub2e4. **g**\ub294 \uadf8\ub798\ud504 \uad00\uacc4\uc785\ub2c8\ub2e4. \uc811\ubbf8\uc0ac\ub97c \uc0ac\uc6a9\ud558\uc5ec **g2**, **g3** \ub4f1\uc744 \ucd94\uac00\ub85c \uc815\uc758\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n:::\\n\\n## \uacc4\uce35\uc801 RBAC {#hierarchical-rbac}\\n\\n\uacc4\uce35\uc801 RBAC\uc5d0\uc11c\ub294 \uc0c1\uc18d \uad00\uacc4\uac00 \uc788\ub294 \uc5ec\ub7ec **resource types**(\uc608: Subscription \u2192 ResourceGroup)\uc774 \uc874\uc7ac\ud569\ub2c8\ub2e4. \uad6c\ub3c5 **sub1**\uc5d0\ub294 \ub9ac\uc18c\uc2a4 \uadf8\ub8f9 **rg1**, **rg2**\uac00 \ud3ec\ud568\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub9c8\ucc2c\uac00\uc9c0\ub85c, \uad6c\ub3c5 \uc218\uc900 \uc5ed\ud560/\uc791\uc5c5\uacfc \ub9ac\uc18c\uc2a4 \uadf8\ub8f9 \uc218\uc900 \uc5ed\ud560/\uc791\uc5c5\uc774 \uc788\uc73c\uba70 \uadf8 \uc0ac\uc774\uc5d0 \uc0c1\uc18d \uad00\uacc4\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \uad6c\ub3c5 \uc5ed\ud560 **sub-owner**\ub294 \ub9ac\uc18c\uc2a4 \uadf8\ub8f9 \uc5ed\ud560 **rg-owner**\ub85c \uc0c1\uc18d\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc989, **sub1**\uc5d0 \ub300\ud574 **sub-owner** \uad8c\ud55c\uc744 \uac00\uc9c0\uace0 \uc788\ub2e4\uba74, \uc2e4\uc9c8\uc801\uc73c\ub85c **rg1** \ubc0f **rg2**\uc5d0 \ub300\ud574 **rg-owner** \uad8c\ud55c\uc744 \uac00\uc9c0\uac8c \ub429\ub2c8\ub2e4.\\n\\n### **Model** \uc815\uc758 {#model-definition-2}\\n\\n\ucd5c\uc18c\ud654\ub41c \uacc4\uce35\uc801 RBAC \ubaa8\ub378:\\n\\n```toml\\n[request_definition]\\nr = sub, act, obj\\n\\n[policy_definition]\\np = sub, act, obj\\n\\n[role_definition]\\ng = _, _\\ng2 = _, _\\n\\n[policy_effect]\\ne = some(where (p.eft == allow))\\n\\n[matchers]\\nm = r.sub == p.sub && g(p.act, r.act) && g2(p.obj, r.obj)\\n```\\n\\n\uc5ec\uae30\uc11c **g**\ub294 \uc5ed\ud560/\uc791\uc5c5\uc744 \uc5f0\uacb0\ud558\uace0 **g2**\ub294 \ub9ac\uc18c\uc2a4\ub97c \uc5f0\uacb0\ud569\ub2c8\ub2e4(\uc608: \uad6c\ub3c5\uc744 \ub9ac\uc18c\uc2a4 \uadf8\ub8f9\uc5d0 \uc5f0\uacb0).\\n\\n### Casbin \uc5d0\ub514\ud130\uc5d0\uc11c \uc2dc\ub3c4\ud574 \ubcf4\uae30 {#try-it-in-the-casbin-editor-2}\\n\\n[\uc5d0\ub514\ud130](https://casbin.org/editor)\ub97c \uc5f4\uace0 \uc704\uc758 \ubaa8\ub378\uc744 \ubd99\uc5ec\ub123\uc73c\uc138\uc694.\\n\\n**Policy editor**\uc5d0 \ub2e4\uc74c \ub0b4\uc6a9\uc744 \ubd99\uc5ec\ub123\uc73c\uc138\uc694:\\n\\n```csv\\np, alice, sub-reader, sub1\\np, bob, rg-owner, rg2\\n\\n// subscription role to subscription action mapping\\ng, sub-reader, sub-read\\ng, sub-owner, sub-read\\ng, sub-owner, sub-write\\n\\n// resourceGroup role to resourceGroup action mapping\\ng, rg-reader, rg-read\\ng, rg-owner, rg-read\\ng, rg-owner, rg-write\\n\\n// subscription role to resourceGroup role mapping\\ng, sub-reader, rg-reader\\ng, sub-owner, rg-owner\\n\\n// subscription resource to resourceGroup resource mapping\\ng2, sub1, rg1\\ng2, sub2, rg2\\n```\\n\\n\uadf8\ub9ac\uace0 **Request editor**\uc5d0 \ub2e4\uc74c \ub0b4\uc6a9\uc744 \ubd99\uc5ec\ub123\uc73c\uc138\uc694:\\n\\n```csv\\nalice, rg-read, rg1\\n```\\n\\n\uacb0\uacfc\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4:\\n\\n```text\\ntrue\\n```\\n\\n### RBAC \ubaa8\ub378, \uc815\ucc45 \ubc0f \uc694\uccad \ub9e4\uce6d\uc758 \uc2dc\uac01\uc801 \ud45c\ud604 {#visual-representation-of-the-rbac-model-policy-and-request-matching-1}\\n\\n![hrbac](/img/tutorial/hrbac.png)\\n\\n**g** \uc5e3\uc9c0(\uc5ed\ud560 \u2192 \uc791\uc5c5, \uc5ed\ud560 \u2192 \uc5ed\ud560)\ub294 \uc815\ucc45\uc5d0\uc11c \ub2e4\uc74c\uacfc \uac19\uc774 \uc791\uc131\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4:\\n\\n```csv\\n// subscription role to subscription action mapping\\ng, sub-reader, sub-read\\ng, sub-owner, sub-read\\ng, sub-owner, sub-write\\n\\n// resourceGroup role to resourceGroup action mapping\\ng, rg-reader, rg-read\\ng, rg-owner, rg-read\\ng, rg-owner, rg-write\\n\\n// subscription role to resourceGroup role mapping\\ng, sub-reader, rg-reader\\ng, sub-owner, rg-owner\\n```\\n\\n**g2** \uc5e3\uc9c0\ub294 \uad6c\ub3c5\uc744 \ub9ac\uc18c\uc2a4 \uadf8\ub8f9\uc5d0 \ub9e4\ud551\ud569\ub2c8\ub2e4:\\n\\n```csv\\n// subscription resource to resourceGroup resource mapping\\ng2, sub1, rg1\\ng2, sub2, rg2\\n```\\n\\n#### \uc8fc\uccb4 \ub9e4\uce6d \uc2dc\uac01\uc801 \ud45c\ud604 {#subject-matching-visual-representation}\\n\\n![hrbac-sub-match](/img/tutorial/hrbac-sub-match.png)\\n\\n#### \uc791\uc5c5 \ub9e4\uce6d \uc2dc\uac01\uc801 \ud45c\ud604 {#action-matching-visual-representation}\\n\\n![hrbac-act-match](/img/tutorial/hrbac-act-match.png)\\n\\n#### \uac1d\uccb4 \ub9e4\uce6d \uc2dc\uac01\uc801 \ud45c\ud604 {#object-matching-visual-representation}\\n\\n![hrbac-obj-match](/img/tutorial/hrbac-obj-match.png)\\n\\n:::info\\nCasbin\uc740 \uc694\uccad\uc744 \ubaa8\ub4e0 \uc815\ucc45\uc5d0 \ub300\ud574 \ud3c9\uac00\ud569\ub2c8\ub2e4. \ucd5c\uc18c\ud55c \ud558\ub098\uc758 \uc815\ucc45\uc774 \uc77c\uce58\ud558\uba74 \uacb0\uacfc\ub294 **true**\uc774\uace0, \uadf8\ub807\uc9c0 \uc54a\uc73c\uba74 **false**\uc785\ub2c8\ub2e4.\\n:::\\n\\n## \uacb0\ub860 {#conclusion}\\n\\n\uc774 \ud29c\ud1a0\ub9ac\uc5bc\uc5d0\uc11c\ub294 ACL, RBAC \ubc0f \uacc4\uce35\ud615 RBAC\uc744 Casbin\uc73c\ub85c \ud45c\ud604\ud558\ub294 \ubc29\ubc95\uc744 \ubcf4\uc5ec \uc8fc\uc5c8\uc2b5\ub2c8\ub2e4. \ud6c4\uc18d \ud3b8\uc5d0\uc11c\ub294 Spring Boot \uc571\uc5d0\uc11c \uc774\ub97c \uad6c\ud604\ud558\uace0 Casbin\uc73c\ub85c API\ub97c \ubcf4\ud638\ud558\ub294 \ubc29\ubc95\uc744 \ub2e4\ub8e8\uaca0\uc2b5\ub2c8\ub2e4."},{"id":"/2021/08/19/apisix-casbin-authorization","metadata":{"permalink":"/ko/blog/2021/08/19/apisix-casbin-authorization","editUrl":"https://github.com/apache/casbin-website/edit/master/i18n/ko/docusaurus-plugin-content-blog/2021-08-19-apisix-casbin-authorization.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2021-08-19-apisix-casbin-authorization.md","title":"Casbin\uc744 \uc0ac\uc6a9\ud558\uc5ec APISIX\uc5d0\uc11c \uc778\uc99d \ucc98\ub9ac","description":"APISIX \uc694\uccad \uacbd\ub85c\uc5d0\uc11c Casbin RBAC\ub97c \uc801\uc6a9\ud558\uace0 \uc5c5\ub370\uc774\ud2b8\ud558\uba70, \uc7ac\ud604 \uac00\ub2a5\ud55c \ud5c8\uc6a9, \uac70\ubd80 \ubc0f \uc815\ub9ac \uac80\uc0ac\ub97c \uc218\ud589\ud569\ub2c8\ub2e4.","date":"2021-08-19T00:00:00.000Z","tags":[],"readingTime":4.54,"hasTruncateMarker":true,"authors":[{"name":"Rushikesh Tote","title":"Member of Casbin","url":"https://github.com/rushitote","imageURL":"/ko/img/authors/rushitote.png","key":"rushitote","page":null},{"name":"Yilia Lin","title":"Apache APISIX Committer","url":"https://github.com/Yilialinn","imageURL":"https://avatars.githubusercontent.com/u/114121331?v=4","key":"yilialin","page":null}],"frontMatter":{"title":"Casbin\uc744 \uc0ac\uc6a9\ud558\uc5ec APISIX\uc5d0\uc11c \uc778\uc99d \ucc98\ub9ac","description":"APISIX \uc694\uccad \uacbd\ub85c\uc5d0\uc11c Casbin RBAC\ub97c \uc801\uc6a9\ud558\uace0 \uc5c5\ub370\uc774\ud2b8\ud558\uba70, \uc7ac\ud604 \uac00\ub2a5\ud55c \ud5c8\uc6a9, \uac70\ubd80 \ubc0f \uc815\ub9ac \uac80\uc0ac\ub97c \uc218\ud589\ud569\ub2c8\ub2e4.","authors":["rushitote","yilialin"]},"unlisted":false,"prevItem":{"title":"Casbin \ub9e4\uce6d \ub3d9\uc791 \uc0c1\uc138 \uc774\ud574","permalink":"/ko/blog/2023/12/08/understanding-casbin-matching-in-detail"},"nextItem":{"title":"Yang Luo \u2014 Google Open Source Peer Bonus \uc218\uc0c1\uc790","permalink":"/ko/blog/2020/04/21/google-award"}},"content":"## \uc18c\uac1c {#introduction}\\n\\n[Apache APISIX](https://apisix.apache.org/)\ub294 \ub0b4\uc7a5 [`authz-casbin`](https://apisix.apache.org/docs/apisix/plugins/authz-casbin/) \ud50c\ub7ec\uadf8\uc778\uc744 \ud1b5\ud574 \uac8c\uc774\ud2b8\uc6e8\uc774\uc5d0\uc11c Casbin \uc778\uc99d \uc815\ucc45\uc744 \uc801\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \ud50c\ub7ec\uadf8\uc778\uc740 [Lua Casbin](https://github.com/apache/casbin-lua-casbin)\uc744 \uc0ac\uc6a9\ud558\uba70 ACL, RBAC, ABAC\uacfc \uac19\uc740 \uc811\uadfc \uc81c\uc5b4 \ubaa8\ub378\uc744 \uc9c0\uc6d0\ud569\ub2c8\ub2e4.\\n\\n\uc774 \uac00\uc774\ub4dc\uc5d0\uc11c\ub294 APISIX \uc694\uccad \uacbd\ub85c\uc5d0 \uc791\uc740 RBAC \uc815\ucc45\uc744 \uc801\uc6a9\ud569\ub2c8\ub2e4. \ud5c8\uc6a9 \ubc0f \uac70\ubd80\ub41c \uc694\uccad\uc744 \uac80\uc99d\ud55c \ud6c4, \ub77c\uc6b0\ud2b8\ub97c \ubcc0\uacbd\ud558\uc9c0 \uc54a\uace0 \ud50c\ub7ec\uadf8\uc778 \uba54\ud0c0\ub370\uc774\ud130\ub97c \ud1b5\ud574 \uacf5\uc720 \uc815\ucc45\uc744 \uc5c5\ub370\uc774\ud2b8\ud569\ub2c8\ub2e4.\\n\\nCasbin \ucee4\ubba4\ub2c8\ud2f0\ub294 \uc6d0\ub798 [APISIX Issue #4674](https://github.com/apache/apisix/issues/4674)\uc5d0\uc11c \ud1b5\ud569\uc744 \uc81c\uc548\ud588\uc73c\uba70, [APISIX PR #4710](https://github.com/apache/apisix/pull/4710)\uc744 \ud1b5\ud574 \ud50c\ub7ec\uadf8\uc778\uc774 \ucd94\uac00\ub418\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n:::info 2026\ub144 8\uc6d4 \uac31\uc2e0\\n\\n\uc774 \uac00\uc774\ub4dc\ub294 2026\ub144 8\uc6d4\uc5d0 \uac31\uc2e0\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uc608\uc81c\ub294 Apache APISIX 3.17.0\uc73c\ub85c \uac80\uc99d\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uc6d0\ubcf8 2021\ub144 \uc800\uc790\uc758 \uacf5\ub85c\ub294 \uadf8\ub300\ub85c \uc720\uc9c0\ub418\uba70, 2026\ub144 \uac31\uc2e0\uc744 \uc704\ud574 Yilia Lin\uc774 \ucd94\uac00\ub85c \uae30\uc7ac\ub418\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n:::\\n\\n\x3c!-- truncate --\x3e\\n\\n:::warning \uc778\uc99d \uacbd\uacc4\\n\\nCasbin\uc740 \uc778\uc99d(authorization)\uc744 \uc218\ud589\ud558\uba70, \uc2e0\uc6d0 \ud655\uc778(authentication)\uc740 \ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ud14c\uc2a4\ud2b8\ub97c \uac04\ub2e8\ud558\uac8c \uc720\uc9c0\ud558\uae30 \uc704\ud574 \uc608\uc81c\uc5d0\uc11c\ub294 `user` \uc694\uccad \ud5e4\ub354\ub97c \uc8fc\uccb4(subject)\ub85c \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \ud504\ub85c\ub355\uc158 \ud658\uacbd\uc5d0\uc11c\ub294 \ud074\ub77c\uc774\uc5b8\ud2b8\uac00 \uc9c1\uc811 \uc81c\uacf5\ud558\ub294 \uc2e0\uc6d0 \ud5e4\ub354\ub97c \uc2e0\ub8b0\ud558\uc9c0 \ub9c8\uc2ed\uc2dc\uc624. \uc778\uc99d \ub808\uc774\uc5b4 \ub610\ub294 \uc2e0\ub8b0\ud560 \uc218 \uc788\ub294 \ud504\ub85d\uc2dc\uac00 \uc2e0\uc6d0\uc744 \ud655\ub9bd\ud558\uace0, Casbin\uc774 \uc694\uccad\uc744 \ud3c9\uac00\ud558\uae30 \uc804\uc5d0 \uc2e0\ub8b0\ud560 \uc218 \uc5c6\ub294 \uac12\uc744 \uc81c\uac70\ud558\uac70\ub098 \ub36e\uc5b4\uc368\uc57c \ud569\ub2c8\ub2e4.\\n\\n:::\\n\\n## \uc0ac\uc804 \uc694\uad6c \uc0ac\ud56d \ubc0f \uc2dc\uc791 \uc0c1\ud0dc {#prerequisites-and-starting-state}\\n\\n\uc774 \uac00\uc774\ub4dc\ub294 \uc774\ubbf8 \uc2e4\ud589 \uc911\uc778 \uc77c\ud68c\uc131 Apache APISIX 3.17.0 \uc778\uc2a4\ud134\uc2a4\ub85c \uc2dc\uc791\ud569\ub2c8\ub2e4. \ub85c\uceec \uc778\uc2a4\ud134\uc2a4\uac00 \ud544\uc694\ud55c \uacbd\uc6b0 [APISIX Docker \ubc30\ud3ec \uac00\uc774\ub4dc](https://apisix.apache.org/docs/docker/manual/)\ub97c \ub530\ub974\uace0 APISIX \uc774\ubbf8\uc9c0\ub97c `apache/apisix:3.17.0-debian`\uc73c\ub85c \uace0\uc815\ud558\uc2ed\uc2dc\uc624.\\n\\n\uc778\uc2a4\ud134\uc2a4\uc5d0\ub294 \ub2e4\uc74c\uc774 \uc788\uc5b4\uc57c \ud569\ub2c8\ub2e4:\\n\\n- `http://127.0.0.1:9080`\uc5d0\uc11c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ub370\uc774\ud130 \ud50c\ub808\uc778;\\n- `http://127.0.0.1:9180`\uc5d0\uc11c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 **Admin API**;\\n- \ub0b4\uc7a5 `authz-casbin` \ubc0f `mocking` \ud50c\ub7ec\uadf8\uc778\uc774 \ud65c\uc131\ud654\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\ub610\ud55c `curl`\uacfc `jq`\uac00 \ud544\uc694\ud569\ub2c8\ub2e4. `admin_key`\ub97c \uad6c\uc131\ud55c\\n**Admin API** \ud0a4\ub85c \uc124\uc815\ud558\uc138\uc694:\\n\\n```sh\\nexport admin_key=\'<your-admin-api-key>\'\\n```\\n\\n\uacc4\uc18d\ud558\uae30 \uc804\uc5d0 \ud50c\ub808\uc774\uc2a4\ud640\ub354\ub97c \uad50\uccb4\ud558\uc138\uc694. **Admin API**\uc5d0 \uc811\uadfc\ud560 \uc218 \uc788\uace0\\n\ud50c\ub7ec\uadf8\uc778\uc774 \ud65c\uc131\ud654\ub418\uc5c8\ub294\uc9c0 \ud655\uc778\ud558\uc138\uc694:\\n\\n```sh\\ncurl --fail-with-body \\\\\\n  \\"http://127.0.0.1:9180/apisix/admin/plugins/list\\" \\\\\\n  -H \\"X-API-KEY: $admin_key\\" | \\\\\\njq -e \'([\\"authz-casbin\\", \\"mocking\\"] - .) | length == 0\'\\n```\\n\\n\uba85\ub839\uc5b4\ub294 `true`\ub97c \ucd9c\ub825\ud574\uc57c \ud569\ub2c8\ub2e4. **Admin API**\ub97c \uc2e0\ub8b0\ud560 \uc218 \uc5c6\ub294 \ub124\ud2b8\uc6cc\ud06c\uc5d0 \uac8c\uc2dc\ud558\uac70\ub098\\n\ub2e4\ub978 \ud658\uacbd\uc5d0\uc11c \ub370\ubaa8 \uc790\uaca9 \uc99d\uba85\uc744 \uc7ac\uc0ac\uc6a9\ud558\uc9c0 \ub9c8\uc138\uc694.\\n\\n## \ubaa8\ub378 \ubc0f \uc815\ucc45 \uc815\uc758 {#define-the-model-and-policy}\\n\\n\ud50c\ub7ec\uadf8\uc778\uc740 \uc138 \uac00\uc9c0 \uc694\uccad \uac12\uc744 \ud3c9\uac00\ud569\ub2c8\ub2e4:\\n\\n- `sub`: \uad6c\uc131\ub41c \uc694\uccad \ud5e4\ub354\uc758 \uc8fc\uccb4(subject);\\n- `obj`: \uc694\uccad URI \uacbd\ub85c; \uadf8\ub9ac\uace0\\n- `act`: HTTP \uba54\uc11c\ub4dc.\\n\\n`model.conf` \uc0dd\uc131:\\n\\n```ini\\n[request_definition]\\nr = sub, obj, act\\n\\n[policy_definition]\\np = sub, obj, act\\n\\n[role_definition]\\ng = _, _\\n\\n[policy_effect]\\ne = some(where (p.eft == allow))\\n\\n[matchers]\\nm = (g(r.sub, p.sub) || keyMatch(r.sub, p.sub)) && keyMatch(r.obj, p.obj) && keyMatch(r.act, p.act)\\n```\\n\\n`policy.csv` \uc0dd\uc131:\\n\\n```csv\\np, *, /anything, GET\\np, admin, *, *\\ng, alice, admin\\n```\\n\\n\uc774 \uc815\ucc45\uc740 \ubaa8\ub4e0 \uc8fc\uccb4\uac00 `GET /anything`\uc744 \uc804\uc1a1\ud558\ub3c4\ub85d \ud5c8\uc6a9\ud569\ub2c8\ub2e4. \ub610\ud55c\\n`alice`\uc5d0\uac8c \ubaa8\ub4e0 \uacbd\ub85c\ub97c \ubaa8\ub4e0 \uba54\uc11c\ub4dc\ub85c \uc811\uadfc\ud560 \uc218 \uc788\ub294 `admin` \uc5ed\ud560\uc744 \ud560\ub2f9\ud569\ub2c8\ub2e4.\\n\\n## \uacf5\uc720 \uc815\ucc45\uc744 \ud50c\ub7ec\uadf8\uc778 \uba54\ud0c0\ub370\uc774\ud130\uc5d0 \uc800\uc7a5 {#store-the-shared-policy-in-plugin-metadata}\\n\\n\ud30c\uc77c\uc744 JSON \ubb38\uc790\uc5f4\ub85c \ub85c\ub4dc\ud558\uace0 APISIX \ud50c\ub7ec\uadf8\uc778 \uba54\ud0c0\ub370\uc774\ud130\uc5d0 \uc501\ub2c8\ub2e4:\\n\\n```sh\\njq -n \\\\\\n  --rawfile model model.conf \\\\\\n  --rawfile policy policy.csv \\\\\\n  \'{model: $model, policy: $policy}\' | \\\\\\ncurl --fail-with-body \\\\\\n  \\"http://127.0.0.1:9180/apisix/admin/plugin_metadata/authz-casbin\\" \\\\\\n  -H \\"X-API-KEY: $admin_key\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -X PUT \\\\\\n  --data-binary @-\\n```\\n\\n\ud50c\ub7ec\uadf8\uc778 \uba54\ud0c0\ub370\uc774\ud130\ub294 \uc790\uccb4 \ub77c\uc6b0\ud2b8 \ub85c\uceec \ubaa8\ub378 \ubc0f \uc815\ucc45\uc744 \uc815\uc758\ud558\uc9c0 \uc54a\uace0\\n`authz-casbin`\uc744 \ud65c\uc131\ud654\ud558\ub294 \ub77c\uc6b0\ud2b8\uc5d0 \ud558\ub098\uc758 \ubaa8\ub378\uacfc \uc815\ucc45\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n## \ub77c\uc6b0\ud2b8\uc5d0\uc11c \uad8c\ud55c \ubd80\uc5ec \ud65c\uc131\ud654 {#enable-authorization-on-a-route}\\n\\n\ub77c\uc6b0\ud2b8\ub97c \uc0dd\uc131\ud558\uace0 \ud50c\ub7ec\uadf8\uc778\uc5d0\uac8c `user` \ud5e4\ub354\uc5d0\uc11c \uc8fc\uccb4\ub97c \uc77d\ub3c4\ub85d \uc9c0\uc2dc\ud569\ub2c8\ub2e4:\\n\\n```sh\\ncurl --fail-with-body \\\\\\n  \\"http://127.0.0.1:9180/apisix/admin/routes/casbin-demo\\" \\\\\\n  -H \\"X-API-KEY: $admin_key\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -X PUT \\\\\\n  -d \'{\\n    \\"uri\\": \\"/*\\",\\n    \\"plugins\\": {\\n      \\"authz-casbin\\": {\\n        \\"username\\": \\"user\\"\\n      },\\n      \\"mocking\\": {\\n        \\"_meta\\": {\\n          \\"priority\\": 1000\\n        },\\n        \\"response_status\\": 200,\\n        \\"response_example\\": \\"{\\\\\\"message\\\\\\":\\\\\\"authorized\\\\\\"}\\"\\n      }\\n    },\\n    \\"upstream\\": {\\n      \\"type\\": \\"roundrobin\\",\\n      \\"nodes\\": {\\n        \\"127.0.0.1:1\\": 1\\n      }\\n    }\\n  }\'\\n```\\n\\n\uc774 \ub77c\uc6b0\ud2b8\ub294 \ub85c\uceec\uc5d0\uc11c `username` \ud544\ub4dc\ub9cc \uc815\uc758\ud558\ubbc0\ub85c \ud50c\ub7ec\uadf8\uc778 \uba54\ud0c0\ub370\uc774\ud130\uc758\\n\ubaa8\ub378\uacfc \uc815\ucc45\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \ub77c\uc6b0\ud2b8 \ub85c\uceec \ubaa8\ub378\uacfc \uc815\ucc45\uc774 \uad6c\uc131\ub41c \uacbd\uc6b0, \ud50c\ub7ec\uadf8\uc778 \uba54\ud0c0\ub370\uc774\ud130\ubcf4\ub2e4\\n\uc6b0\uc120\ud569\ub2c8\ub2e4.\\n\\n`mocking` \ud50c\ub7ec\uadf8\uc778\uc740 \ud5c8\uc6a9\ub41c \uc694\uccad\uc5d0 \ub300\ud574 \uacb0\uc815\uc801\uc778 \ub85c\uceec \uc751\ub2f5\uc744 \uc81c\uacf5\ud558\ubbc0\ub85c,\\n\uc608\uc81c\uac00 \uacf5\uac1c \uc5c5\uc2a4\ud2b8\ub9bc\uc5d0 \uc758\uc874\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ud574\ub2f9 \ub77c\uc6b0\ud2b8 \ub85c\uceec \uc6b0\uc120\uc21c\uc704\ub294\\n`authz-casbin`\ubcf4\ub2e4 \ub0ae\uc544 \uad8c\ud55c \uacb0\uc815\uc744 \uba3c\uc800 \uc2e4\ud589\ud569\ub2c8\ub2e4.\\n\ub530\ub77c\uc11c \ub3c4\ub2ec\ud560 \uc218 \uc5c6\ub294 \uc5c5\uc2a4\ud2b8\ub9bc\uc740 \uc5f0\uacb0\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc774 \uc6b0\uc120\uc21c\uc704 \uc624\ubc84\ub77c\uc774\ub4dc\uc640\\n\ubaa8\uc758 \uc751\ub2f5\uc740 \ud14c\uc2a4\ud2b8 \ud53d\uc2a4\ucc98\uc774\uba70, \ud504\ub85c\ub355\uc158 \uad8c\uc7a5 \uc0ac\ud56d\uc774 \uc544\ub2d9\ub2c8\ub2e4.\\n\\n## \ud5c8\uc6a9 \ubc0f \uac70\ubd80 \uacb0\uc815 \uac80\uc99d {#verify-allow-and-deny-decisions}\\n\\n\uacf5\uac1c \uacbd\ub85c\uc5d0 \ub300\ud55c \uc775\uba85 \uc694\uccad\uc740 \ud5c8\uc6a9\ub429\ub2c8\ub2e4:\\n\\n```sh\\ncurl -i http://127.0.0.1:9080/anything\\n```\\n\\n\uae30\ub300 \uc0c1\ud0dc \ucf54\ub4dc:\\n\\n```text\\nHTTP/1.1 200 OK\\n{\\"message\\":\\"authorized\\"}\\n```\\n\\n`bob`\uc740 `admin` \uc5ed\ud560\uc774 \uc5c6\uc73c\ubbc0\ub85c \ub2e4\ub978 \uacbd\ub85c\ub294 \uac70\ubd80\ub429\ub2c8\ub2e4:\\n\\n```sh\\ncurl -i http://127.0.0.1:9080/anything/res -H \'user: bob\'\\n```\\n\\n\uae30\ub300 \uacb0\uacfc:\\n\\n```text\\nHTTP/1.1 403 Forbidden\\n{\\"message\\":\\"Access Denied\\"}\\n```\\n\\n`alice`\ub294 `admin` \uc5ed\ud560\uc774 \uc788\uc73c\ubbc0\ub85c \ub3d9\uc77c\ud55c \uc694\uccad\uc740 \ud5c8\uc6a9\ub429\ub2c8\ub2e4:\\n\\n```sh\\ncurl -i http://127.0.0.1:9080/anything/res -H \'user: alice\'\\n```\\n\\n\uae30\ub300 \uc0c1\ud0dc \ucf54\ub4dc:\\n\\n```text\\nHTTP/1.1 200 OK\\n{\\"message\\":\\"authorized\\"}\\n```\\n\\n## \uacf5\uc720 \uc815\ucc45 \uc5c5\ub370\uc774\ud2b8 {#update-the-shared-policy}\\n\\n`bob`\uc744 \uc704\ud55c \uc9c1\uc811 \uad8c\ud55c\uc744 `policy.csv`\uc5d0 \ucd94\uac00\ud569\ub2c8\ub2e4:\\n\\n```csv\\np, *, /anything, GET\\np, admin, *, *\\np, bob, /anything/res, GET\\ng, alice, admin\\n```\\n\\n\ud50c\ub7ec\uadf8\uc778 \uba54\ud0c0\ub370\uc774\ud130 \uba85\ub839\uc744 \ub2e4\uc2dc \uc2e4\ud589\ud558\uc138\uc694. \uc774 \uba54\ud0c0\ub370\uc774\ud130\ub97c \ucc38\uc870\ud558\ub294 \ub77c\uc6b0\ud2b8\ub294\\n\ub77c\uc6b0\ud2b8 \uad6c\uc131\uc744 \ubcc0\uacbd\ud558\uc9c0 \uc54a\uace0\ub3c4 \uc5c5\ub370\uc774\ud2b8\ub41c \uc815\ucc45\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uc694\uccad\uc744 \ubc18\ubcf5\ud558\uc138\uc694:\\n\\n```sh\\ncurl -i http://127.0.0.1:9080/anything/res -H \'user: bob\'\\n```\\n\\n\uc774\uc81c \uae30\ub300 \uacb0\uacfc\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4:\\n\\n```text\\nHTTP/1.1 200 OK\\n{\\"message\\":\\"authorized\\"}\\n```\\n\\n## \uad6c\uc131 \ubc94\uc704 \uc120\ud0dd {#choosing-the-configuration-scope}\\n\\n\uc5ec\ub7ec \ub77c\uc6b0\ud2b8\uac00 \ud558\ub098\uc758 \ubaa8\ub378\uacfc \uc815\ucc45\uc744 \uacf5\uc720\ud574\uc57c \ud558\ub294 \uacbd\uc6b0 \ud50c\ub7ec\uadf8\uc778 \uba54\ud0c0\ub370\uc774\ud130\ub97c \uc0ac\uc6a9\ud558\uc138\uc694.\\n\ub77c\uc6b0\ud2b8\uac00 \ub3c5\ub9bd\uc801\uc778 \uad8c\ud55c \uad6c\uc870\uac00 \ud544\uc694\ud55c \uacbd\uc6b0 \ub77c\uc6b0\ud2b8 \ub85c\uceec \ubaa8\ub378\uacfc \uc815\ucc45\uc744 \uc0ac\uc6a9\ud558\uc138\uc694.\\n\uc804\uccb4 \uad6c\uc131 \uc2a4\ud0a4\ub9c8 \ubc0f \ud30c\uc77c \uae30\ubc18 \ub300\uc548\uc740 [APISIX `authz-casbin` \ud50c\ub7ec\uadf8\uc778 \ub808\ud37c\ub7f0\uc2a4](https://apisix.apache.org/docs/apisix/plugins/authz-casbin/)\ub97c \ucc38\uace0\ud558\uc138\uc694.\\n\\n## \uc815\ub9ac {#clean-up}\\n\\n\ud14c\uc2a4\ud2b8 \ub77c\uc6b0\ud2b8 \uc81c\uac70:\\n\\n```sh\\ncurl --fail-with-body \\\\\\n  \\"http://127.0.0.1:9180/apisix/admin/routes/casbin-demo\\" \\\\\\n  -H \\"X-API-KEY: $admin_key\\" \\\\\\n  -X DELETE\\n```\\n\\n\uacf5\uc720 \ud50c\ub7ec\uadf8\uc778 \uba54\ud0c0\ub370\uc774\ud130 \uc81c\uac70:\\n\\n```sh\\ncurl --fail-with-body \\\\\\n  \\"http://127.0.0.1:9180/apisix/admin/plugin_metadata/authz-casbin\\" \\\\\\n  -H \\"X-API-KEY: $admin_key\\" \\\\\\n  -X DELETE\\n```"},{"id":"/2020/04/21/google-award","metadata":{"permalink":"/ko/blog/2020/04/21/google-award","editUrl":"https://github.com/apache/casbin-website/edit/master/i18n/ko/docusaurus-plugin-content-blog/2020-04-21-google-award.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2020-04-21-google-award.md","title":"Yang Luo \u2014 Google Open Source Peer Bonus \uc218\uc0c1\uc790","description":"Casbin\uc758 \ucc3d\ub9bd\uc790 Yang Luo\uac00 2019\ub144 3\ubd84\uae30\uc5d0 Casbin, Npcap, Nmap\uc5d0\uc11c\uc758 \uacf5\ub85c\ub85c Google Open Source Peer Bonus \uc218\uc0c1\uc790\ub85c \uc120\uc815\ub418\uc5c8\uc74c\uc744 \uae30\uc058\uac8c \ubc1c\ud45c\ud569\ub2c8\ub2e4.","date":"2020-04-21T00:00:00.000Z","tags":[],"readingTime":0.81,"hasTruncateMarker":true,"authors":[{"name":"Casbin","title":"Official Account","url":"https://github.com/casbin","imageURL":"/ko/img/authors/casbin.png","key":"casbin","page":null}],"frontMatter":{"title":"Yang Luo \u2014 Google Open Source Peer Bonus \uc218\uc0c1\uc790","authors":["casbin"]},"unlisted":false,"prevItem":{"title":"Casbin\uc744 \uc0ac\uc6a9\ud558\uc5ec APISIX\uc5d0\uc11c \uc778\uc99d \ucc98\ub9ac","permalink":"/ko/blog/2021/08/19/apisix-casbin-authorization"},"nextItem":{"title":"\ubb38\uc11c \uc7ac\uc791\uc5c5 \uc911","permalink":"/ko/blog/2018/09/23/new-website"}},"content":"Casbin\uc758 \ucc3d\ub9bd\uc790 [Yang Luo](https://github.com/hsluoyz)\uac00 2019\ub144 3\ubd84\uae30\uc5d0 [Casbin](/), [Npcap](https://nmap.org/npcap/), [Nmap](https://nmap.org/)\uc5d0\uc11c\uc758 \uacf5\ub85c\ub85c [Google Open Source Peer Bonus](https://opensource.google.com/docs/growing/peer-bonus/) \uc218\uc0c1\uc790\ub85c \uc120\uc815\ub418\uc5c8\uc74c\uc744 \uae30\uc058\uac8c \ubc1c\ud45c\ud569\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n![ospb](/img/blog/google-open-source-peer-bonus-award-letter.png)\\n\\n> \uc804\uccb4 \uc0c1\uc7a5 \ubb38\uc11c\ub294 [\uc5ec\uae30](https://github.com/hsluoyz/hsluoyz.github.io/blob/master/download/Open%20Source%20Peer%20Bonus%20Q3%202019%20-%20Yang%20Luo%20-%20OSPB%20Award%20Letter.pdf)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\nGoogle\uc740 \uc774 \ud504\ub85c\uadf8\ub7a8\uc744 \ub2e4\uc74c\uacfc \uac19\uc774 \uc124\uba85\ud569\ub2c8\ub2e4:\\n\\n> _\ub9c8\uce58 Google Peer Bonus\uac00 \uae30\ub300 \uc774\uc0c1\uc758 \uc131\uacfc\ub97c \ub0b8 \ub3d9\ub8cc Googler\ub97c \uc778\uc815\ud558\ub4ef, Open Source Peer Bonus\ub294 \uc624\ud508 \uc18c\uc2a4\uc5d0 \ud0c1\uc6d4\ud55c \uae30\uc5ec\ub97c \ud55c \uc678\ubd80 \uae30\uc5ec\uc790\ub97c \uc778\uc815\ud569\ub2c8\ub2e4._\\n\\n[2019\ub144 \uc218\uc0c1\uc790 \ubc1c\ud45c](https://opensource.googleblog.com/2020/01/announcing-2019-second-cycle-google.html)\uc5d0\uc11c\ub294 Yang\uacfc Casbin\uc744 Git, TensorFlow, V8, CPython, LLVM, Apache \ud504\ub85c\uc81d\ud2b8, Angular, Jenkins \ub4f1 \uc601\ud5a5\ub825 \uc788\ub294 \ub2e4\ub978 \ud504\ub85c\uc81d\ud2b8 \ubc0f \uac1c\ubc1c\uc790\ub4e4\uacfc \ud568\uaed8 \ub098\uc5f4\ud588\uc2b5\ub2c8\ub2e4.\\n\\n\uc624\ud508 \uc18c\uc2a4 \ubc0f \ud074\ub77c\uc6b0\ub4dc \ubcf4\uc548 \ubd84\uc57c\uc5d0\uc11c Casbin\uc774 \uc778\uc815\ubc1b\uac8c \ub418\uc5b4 \uc790\ub791\uc2a4\ub7fd\uc2b5\ub2c8\ub2e4.\\n\\n_Casbin\uc744 \uc774\uc6a9\ud574 \uc8fc\uc154\uc11c \uac10\uc0ac\ud569\ub2c8\ub2e4!_"},{"id":"/2018/09/23/new-website","metadata":{"permalink":"/ko/blog/2018/09/23/new-website","editUrl":"https://github.com/apache/casbin-website/edit/master/i18n/ko/docusaurus-plugin-content-blog/2018-09-23-new-website.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2018-09-23-new-website.md","title":"\ubb38\uc11c \uc7ac\uc791\uc5c5 \uc911","description":"Casbin \ubb38\uc11c\ub97c GitHub Wiki\uc5d0\uc11c Docusaurus \uae30\ubc18 \uc774 \uc0ac\uc774\ud2b8\uc758 Docs \uc139\uc158\uc73c\ub85c \uc774\ub3d9\ud588\uc2b5\ub2c8\ub2e4. \ub354 \ub098\uc740 Markdown \ub80c\ub354\ub9c1, \uc804\ubb38 \uac80\uc0c9, \ubc84\uc804 \uad00\ub9ac \ubc0f \ubc88\uc5ed \uae30\ub2a5\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4.","date":"2018-09-23T00:00:00.000Z","tags":[],"readingTime":0.21,"hasTruncateMarker":true,"authors":[{"name":"Yang Luo","title":"Creator of Casbin","url":"https://github.com/hsluoyz","imageURL":"/ko/img/authors/hsluoyz.png","key":"hsluoyz","page":null}],"frontMatter":{"title":"\ubb38\uc11c \uc7ac\uc791\uc5c5 \uc911","authors":["hsluoyz"]},"unlisted":false,"prevItem":{"title":"Yang Luo \u2014 Google Open Source Peer Bonus \uc218\uc0c1\uc790","permalink":"/ko/blog/2020/04/21/google-award"},"nextItem":{"title":"node-Casbin: Casbin \uac00\uc871\uc758 \uc0c8\ub85c\uc6b4 \uad6c\uc131\uc6d0","permalink":"/ko/blog/2018/08/27/node-casbin"}},"content":"Casbin \ubb38\uc11c\ub97c GitHub Wiki\uc5d0\uc11c Docusaurus \uae30\ubc18 \uc774 \uc0ac\uc774\ud2b8\uc758 **Docs** \uc139\uc158\uc73c\ub85c \uc774\ub3d9\ud588\uc2b5\ub2c8\ub2e4. \ub354 \ub098\uc740 Markdown \ub80c\ub354\ub9c1, \uc804\ubb38 \uac80\uc0c9, \ubc84\uc804 \uad00\ub9ac \ubc0f \ubc88\uc5ed \uae30\ub2a5\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n\ubb38\uc11c\ub294 \uacc4\uc18d \uac1c\uc120\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc0ac\uc774\ud2b8 \uc18c\uc2a4\ub294 GitHub\uc5d0 \uc788\uc2b5\ub2c8\ub2e4: https://github.com/apache/casbin-website\\n\\n\uae30\uc5ec\uc640 \uc81c\uc548\uc744 \ud658\uc601\ud569\ub2c8\ub2e4."},{"id":"/2018/08/27/node-casbin","metadata":{"permalink":"/ko/blog/2018/08/27/node-casbin","editUrl":"https://github.com/apache/casbin-website/edit/master/i18n/ko/docusaurus-plugin-content-blog/2018-08-27-node-casbin.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2018-08-27-node-casbin.md","title":"node-Casbin: Casbin \uac00\uc871\uc758 \uc0c8\ub85c\uc6b4 \uad6c\uc131\uc6d0","description":"\uc6b0\ub9ac\ub294 Casbin\uc744 Node.js\ub85c \ud3ec\ud305\ud588\uc2b5\ub2c8\ub2e4: node-Casbin.","date":"2018-08-27T00:00:00.000Z","tags":[],"readingTime":0.27,"hasTruncateMarker":true,"authors":[{"name":"Zixuan Liu","title":"Casbin Maintainer","url":"https://github.com/nodece","imageURL":"/ko/img/authors/nodece.png","key":"nodece","page":null}],"frontMatter":{"title":"node-Casbin: Casbin \uac00\uc871\uc758 \uc0c8\ub85c\uc6b4 \uad6c\uc131\uc6d0","authors":["nodece"]},"unlisted":false,"prevItem":{"title":"\ubb38\uc11c \uc7ac\uc791\uc5c5 \uc911","permalink":"/ko/blog/2018/09/23/new-website"},"nextItem":{"title":"**Casbin Server** \ucd9c\uc2dc!","permalink":"/ko/blog/2018/08/07/launching-casbin-server"}},"content":"\uc6b0\ub9ac\ub294 Casbin\uc744 Node.js\ub85c \ud3ec\ud305\ud588\uc2b5\ub2c8\ub2e4: [node-Casbin](https://github.com/apache/casbin-node-casbin).\\n\\n\x3c!-- truncate --\x3e\\n\\n**node-Casbin**\uc740 \ub2e4\ub978 Casbin \uad6c\ud604\uccb4\uc640 \ub3d9\uc77c\ud55c \uc0ac\uc6a9\ubc95\uacfc API\ub97c \uc720\uc9c0\ud569\ub2c8\ub2e4. Express, Koa2, Egg.js\uc6a9 \ubbf8\ub4e4\uc6e8\uc5b4\uac00 \uc81c\uacf5\ub418\uba70, Sequelize \uc2a4\ud1a0\ub9ac\uc9c0 \uc5b4\ub311\ud130\uac00 \ud3ec\ud568\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uadc0\ud558\uc758 \uae30\uc220 \uc2a4\ud0dd\uc5d0 \uc798 \ub9de\uae30\ub97c \ubc14\ub78d\ub2c8\ub2e4. \ud53c\ub4dc\ubc31\uacfc \uae30\uc5ec\ub97c \ud658\uc601\ud569\ub2c8\ub2e4.\\n\\nGitHub: https://github.com/apache/casbin-node-casbin"},{"id":"/2018/08/07/launching-casbin-server","metadata":{"permalink":"/ko/blog/2018/08/07/launching-casbin-server","editUrl":"https://github.com/apache/casbin-website/edit/master/i18n/ko/docusaurus-plugin-content-blog/2018-08-07-launching-casbin-server.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2018-08-07-launching-casbin-server.md","title":"**Casbin Server** \ucd9c\uc2dc!","description":"\uc0ac\ub78c\ub4e4\uc740 Casbin\uc744 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc544\ub2cc \uc11c\ube44\uc2a4\ub85c \uc2e4\ud589\ud560 \uc218 \uc788\ub294\uc9c0 \uc790\uc8fc \ubb3b\uc2b5\ub2c8\ub2e4. \uc815\ub2f5\uc740 \uc608\uc785\ub2c8\ub2e4. \uc6b0\ub9ac\ub294 \uad6c\uccb4\uc801\uc778 Access Control as a Service \uc194\ub8e8\uc158\uc73c\ub85c Casbin Server\ub97c \ucd9c\uc2dc\ud588\uc2b5\ub2c8\ub2e4.","date":"2018-08-07T00:00:00.000Z","tags":[],"readingTime":0.43,"hasTruncateMarker":true,"authors":[{"name":"Helong Zhang","title":"Casbin Maintainer","url":"https://github.com/BetaCat0","imageURL":"/ko/img/authors/BetaCat0.png","key":"BetaCat0","page":null}],"frontMatter":{"title":"**Casbin Server** \ucd9c\uc2dc!","authors":["BetaCat0"]},"unlisted":false,"prevItem":{"title":"node-Casbin: Casbin \uac00\uc871\uc758 \uc0c8\ub85c\uc6b4 \uad6c\uc131\uc6d0","permalink":"/ko/blog/2018/08/27/node-casbin"}},"content":"\uc0ac\ub78c\ub4e4\uc740 Casbin\uc744 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc544\ub2cc \uc11c\ube44\uc2a4\ub85c \uc2e4\ud589\ud560 \uc218 \uc788\ub294\uc9c0 \uc790\uc8fc \ubb3b\uc2b5\ub2c8\ub2e4. \uc815\ub2f5\uc740 **\uc608**\uc785\ub2c8\ub2e4. \uc6b0\ub9ac\ub294 \uad6c\uccb4\uc801\uc778 **Access Control as a Service** \uc194\ub8e8\uc158\uc73c\ub85c [Casbin Server](https://github.com/apache/casbin-server)\ub97c \ucd9c\uc2dc\ud588\uc2b5\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n**Casbin Server**\ub294 \ucf54\uc5b4 \ud300\uc774 \ud65c\ubc1c\ud558\uac8c \uac1c\ubc1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ud604\uc7ac \uae30\ub2a5:\\n\\n- Go \uc5b8\uc5b4\ub85c \uc791\uc131\ub418\uc5c8\uc2b5\ub2c8\ub2e4.\\n- \uc5ec\ub7ec Casbin \uc778\uc2a4\ud134\uc2a4\ub97c \uad00\ub9ac\ud558\uc5ec \uc5ec\ub7ec \uc11c\ube44\uc2a4\uc5d0\uc11c \uc815\ucc45 \uc801\uc6a9\uc744 \uc911\uc559\ud654\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- \ubaa8\ub4e0 \ud074\ub77c\uc774\uc5b8\ud2b8 \ud1b5\uc2e0\uc5d0 **gRPC** \uc0ac\uc6a9; **REST** \uc9c0\uc6d0 \uc608\uc815.\\n- \uc778\uc2a4\ud134\uc2a4, \ubaa8\ub378, \uc815\ucc45 \uc800\uc7a5\uc18c \ubc0f \ub85c\ub4dc \ubc38\ub7f0\uc2f1\uc744 \uad00\ub9ac\ud558\ub294 \uc6f9 \uad00\ub9ac\uc790 UI.\\n\\n\uc18c\uc2a4 \ucf54\ub4dc: https://github.com/apache/casbin-server\\n\\n\uc774\uc288\uc640 \ud480 \ub9ac\ud018\uc2a4\ud2b8\ub97c \ud658\uc601\ud569\ub2c8\ub2e4."}]}}')}}]);